/** Initial reviewed quiz sets (draft). Each set has 11 basic, 3 application, 1 challenge question. */
export type HGQuestionLevel = 'basic' | 'application' | 'challenge';
export type HGQuizQuestion = { id:string; level:HGQuestionLevel; prompt:string; options:[string,string,string,string]; answer:0|1|2|3; explanation:string };
export type HGQuizSet = { lessonId:string; grade:6|7|8|9; strand:'history'; title:string; questions:HGQuizQuestion[]; status:'draft' };
type RawQ = [string,string,string,string,string,number,string];
function buildQuestions(prefix:string, rows:RawQ[]): HGQuizQuestion[] { return rows.map((r,i)=>({id:prefix+'-q'+String(i+1).padStart(2,'0'),level:i<11?'basic':i<14?'application':'challenge',prompt:r[0],options:[r[1],r[2],r[3],r[4]],answer:r[5] as 0|1|2|3,explanation:r[6]})); }
export const historyGeographyQuizDrafts:HGQuizSet[] = [
  {lessonId:"hg6-history-time-sources",grade:6,strand:'history',title:"Lịch sử, tư liệu và dòng thời gian",questions:buildQuestions("hg6-history-sources",[["Tư liệu lịch sử giúp chúng ta làm gì?","Tìm hiểu quá khứ","Dự đoán thời tiết","Tính diện tích","Đổi đơn vị",0,"Tư liệu cung cấp thông tin để tìm hiểu và giải thích quá khứ."],["Đâu là tư liệu hiện vật?","Bài đăng mới","Trống đồng cổ","Dự báo","Ý kiến chưa kiểm chứng",1,"Hiện vật là vật còn lại từ quá khứ, có thể được nghiên cứu."],["Dòng thời gian dùng để thể hiện điều gì?","Độ dài văn bản","Địa hình","Thứ tự sự kiện theo thời gian","Nhiệt độ",2,"Dòng thời gian sắp xếp sự kiện trước–sau."],["Tư liệu chữ viết có thể là gì?","Bản ghi chép cổ","Một cơn mưa","Một ngọn núi","Một phép đo mới",0,"Văn bản, thư tịch, bia ký là nguồn chữ viết."],["Năm 938 diễn ra trước hay sau năm 1000?","Sau","Cùng lúc","Không thể xác định","Trước",3,"938 nhỏ hơn 1000 nên diễn ra trước."],["Một di tích được tìm thấy cần được nghiên cứu trong bối cảnh nào?","Chỉ nhìn màu sắc","Bối cảnh địa điểm, thời đại và các bằng chứng liên quan","Không cần ghi nhận","Chỉ nghe kể",1,"Bối cảnh giúp giải thích ý nghĩa và niên đại di tích."],["Tư liệu truyền miệng có thể gồm?","Truyện kể được lưu truyền","Máy đo hiện đại","Bản đồ vệ tinh mới","Hóa đơn hôm nay",0,"Truyện, ký ức và lời kể truyền qua các thế hệ có thể là tư liệu truyền miệng."],["Vì sao cần ghi nguồn khi sử dụng tư liệu?","Để làm bài dài hơn","Để tránh đọc","Để người khác kiểm tra xuất xứ và độ tin cậy","Để đổi chủ đề",2,"Ghi nguồn giúp kiểm tra và đánh giá thông tin."],["Nếu tư liệu có dấu hiệu bị hư hỏng, người nghiên cứu nên?","Tự sửa nội dung","Bảo quản và nhờ chuyên môn đánh giá","Bỏ đi ngay","Kết luận không cần kiểm tra",1,"Tư liệu cần được bảo quản, khảo sát đúng phương pháp."],["Một sự kiện có nhiều cách kể. Cách học phù hợp là?","So sánh các nguồn và bối cảnh","Chọn lời kể hấp dẫn nhất","Bỏ mọi nguồn","Chỉ tin một người",0,"Đối chiếu nhiều nguồn giúp hiểu và đánh giá thông tin."],["Lịch sử nghiên cứu chủ yếu về?","Các dự đoán","Những điều chưa xảy ra","Chỉ thiên nhiên","Hoạt động và biến đổi của con người trong quá khứ",3,"Lịch sử tìm hiểu quá khứ của con người và xã hội."],["Sự kiện A năm 1200, B năm 1250. Khoảng cách năm là?","25","50","100","150",1,"1250−1200=50 năm."],["Một hiện vật phát hiện cùng lớp đất với nhiều vật khác. Điều đó gợi ý?","Cần khảo sát mối liên hệ và tầng văn hóa","Chắc chắn cùng người chế tác","Không có giá trị","Có thể bỏ qua",0,"Tầng khảo cổ và liên hệ hiện vật là căn cứ cần nghiên cứu thêm, không tự khẳng định."],["Vì sao ảnh chụp di tích cũng hữu ích?","Thay hoàn toàn mọi nghiên cứu","Chỉ để trang trí","Ghi lại đặc điểm, hỗ trợ quan sát và đối chiếu","Không cung cấp thông tin",2,"Ảnh có thể ghi nhận trạng thái và chi tiết di tích ở thời điểm chụp."],["Khi kết luận lịch sử, nên?","Khẳng định theo cảm tính","Dùng bằng chứng, cân nhắc giới hạn tư liệu","Không cần dẫn chứng","Chỉ dựa vào một câu truyền miệng",1,"Kết luận lịch sử cần dựa trên bằng chứng và đánh giá độ tin cậy."]]),status:'draft'},
  {lessonId:"hg7-history-explorations",grade:7,strand:'history',title:"Khởi nghĩa Lam Sơn và khôi phục độc lập",questions:buildQuestions("hg7-history-explorations",[["Khởi nghĩa Lam Sơn bắt đầu năm nào?","1407","1418","1427","1431",1,"Khởi nghĩa Lam Sơn bắt đầu năm 1418."],["Người lãnh đạo cuộc khởi nghĩa Lam Sơn là ai?","Lê Lợi","Trần Hưng Đạo","Quang Trung","Ngô Quyền",0,"Lê Lợi là người lãnh đạo cuộc khởi nghĩa."],["Khởi nghĩa Lam Sơn diễn ra chống lại ách đô hộ của?","Nhà Tống","Nhà Thanh","Nhà Minh","Nhà Nguyên",2,"Cuộc khởi nghĩa chống sự đô hộ của nhà Minh."],["Hội thề Lũng Nhai gắn với giai đoạn nào?","Chuẩn bị lực lượng khởi nghĩa","Kết thúc chiến tranh","Thời Nguyễn","Thời Pháp thuộc",0,"Hội thề Lũng Nhai gắn với sự chuẩn bị khởi nghĩa Lam Sơn."],["Nguyễn Trãi có đóng góp nổi bật nào?","Chỉ xây thành","Chỉ làm thương nhân","Không liên quan","Tham mưu, chính trị và văn chương phục vụ khởi nghĩa",3,"Nguyễn Trãi đóng góp về chiến lược, chính trị và tư tưởng."],["Chiến thắng nào năm 1427 góp phần quyết định kết thúc chiến tranh?","Bạch Đằng 938","Chiến thắng Chi Lăng–Xương Giang","Rạch Gầm–Xoài Mút","Ngọc Hồi",1,"Chiến thắng Chi Lăng–Xương Giang làm suy sụp viện binh Minh."],["Lê Lợi lên ngôi vua, mở đầu triều Lê sơ, vào năm nào?","1428","1400","1471","1527",0,"Chiến tranh kết thúc năm 1427; năm 1428 Lê Lợi lên ngôi và lập triều Lê sơ."],["Hội nghị Đông Quan có ý nghĩa chủ yếu?","Mở đầu khởi nghĩa","Chia lãnh thổ","Góp phần giải quyết việc kết thúc chiến tranh và rút quân","Bắt đầu thời Bắc thuộc",2,"Hội nghị gắn với việc hòa giải, kết thúc chiến tranh và rút quân Minh."],["Tại sao nghĩa quân từng hoạt động ở vùng núi Thanh Hóa?","Vì không có dân cư","Địa bàn thuận lợi xây dựng căn cứ và tổ chức lực lượng","Để tránh mọi giao tranh","Do không có đường đi",1,"Địa hình và sự hỗ trợ tại địa phương giúp xây dựng căn cứ."],["Chiến lược tiến triển từ khó khăn đến chủ động phản công cho thấy?","Vai trò tổ chức, căn cứ và điều chỉnh chiến lược","Không cần hậu cần","Chỉ thắng nhờ may mắn","Không có thay đổi",0,"Tổ chức, hậu cần và chiến lược góp phần tạo chuyển biến."],["Lam Sơn thuộc địa bàn tỉnh nào ngày nay?","Quảng Ninh","Nghệ An","Thanh Hóa","Bình Định",2,"Lam Sơn thuộc Thanh Hóa."],["Vì sao thắng lợi năm 1428 có ý nghĩa lớn?","Chấm dứt mọi xung đột thế giới","Khôi phục độc lập và mở đầu triều Lê sơ","Chuyển sang thuộc địa","Xóa bỏ sản xuất",1,"Thắng lợi khôi phục độc lập, tạo nền tảng xây dựng quốc gia."],["Tư liệu nào hữu ích khi nghiên cứu khởi nghĩa?","Chỉ phim hư cấu","Chỉ quảng cáo","Chỉ lời đồn","Sử liệu, văn bia, văn bản và di tích được kiểm chứng",3,"Nhiều loại sử liệu cần được đối chiếu và kiểm tra."],["Nếu bản đồ cho thấy các tuyến tiến quân, học sinh có thể rút ra?","Mối liên hệ giữa địa hình, vị trí và chiến lược","Chính xác mọi chi tiết trận đánh","Không cần đọc chú giải","Thời tiết chắc chắn",0,"Bản đồ giúp phân tích không gian, nhưng cần chú giải và nguồn."],["Đánh giá cuộc khởi nghĩa nên chú ý?","Chỉ số lượng trận","Chỉ một nhân vật","Nguyên nhân, diễn biến, kết quả và ý nghĩa","Bỏ bối cảnh",2,"Phân tích toàn diện gồm bối cảnh, diễn biến, kết quả và ý nghĩa."]]),status:'draft'},
  {lessonId:"hg8-history-industrial",grade:8,strand:'history',title:"Cách mạng công nghiệp và xã hội",questions:buildQuestions("hg8-history-industrial",[["Cách mạng công nghiệp lần thứ nhất khởi đầu ở?","Anh","Pháp","Mỹ","Nga",0,"Cách mạng công nghiệp lần thứ nhất khởi đầu ở Anh."],["Thời điểm khởi đầu thường được xác định vào?","Thế kỉ XV","Cuối thế kỉ XVIII","Cuối thế kỉ XX","Thế kỉ XXI",1,"Quá trình khởi đầu ở Anh vào cuối thế kỉ XVIII."],["Máy hơi nước cải tiến gắn với tên tuổi?","Galileo","Newton","James Watt","Einstein",2,"James Watt có đóng góp quan trọng trong cải tiến máy hơi nước."],["Cơ giới hóa có tác động trực tiếp nào?","Giảm vai trò máy móc","Chấm dứt nhà máy","Không đổi năng suất","Tăng năng lực sản xuất",3,"Máy móc góp phần tăng năng suất và thay đổi tổ chức sản xuất."],["Ngành nào phát triển sớm trong cách mạng công nghiệp ở Anh?","Dệt","Hàng không vũ trụ","Điện tử vi mạch","Công nghệ gen",0,"Ngành dệt là một trong những ngành cơ giới hóa sớm."],["Công nghiệp hóa góp phần thúc đẩy?","Giảm mọi trao đổi","Đô thị hóa","Xóa bỏ giao thông","Ngừng di cư",1,"Nhà máy và việc làm thúc đẩy dân cư tập trung ở đô thị."],["Hệ quả xã hội của công nghiệp hóa bao gồm?","Chỉ lợi ích đồng đều","Không thay đổi xã hội","Hình thành tầng lớp công nhân công nghiệp","Chấm dứt lao động",2,"Công nhân công nghiệp trở thành một tầng lớp xã hội quan trọng."],["Vì sao giao thông phát triển quan trọng?","Làm hàng hóa không lưu thông","Chỉ phục vụ nông thôn","Không liên quan sản xuất","Hỗ trợ vận chuyển nguyên liệu và sản phẩm",3,"Giao thông kết nối vùng nguyên liệu, nhà máy và thị trường."],["Một mặt hàng làm bằng máy rẻ hơn, sản xuất nhanh hơn. Điều này có thể?","Mở rộng thị trường tiêu dùng","Giảm nguồn cung chắc chắn","Chấm dứt thương mại","Làm mọi hàng hóa khan hiếm",0,"Năng suất cao có thể làm tăng nguồn cung và mở rộng thị trường."],["Làm việc tại nhà máy thời đầu có thể gặp vấn đề gì?","Luôn an toàn tuyệt đối","Điều kiện lao động kéo dài và thiếu an toàn","Không có giờ làm","Không có người lao động",1,"Nhiều nhà máy thời đầu có điều kiện lao động khắc nghiệt."],["Công nghiệp hóa tác động môi trường như thế nào?","Không tác động","Chỉ làm sạch không khí","Có thể tăng ô nhiễm và khai thác tài nguyên","Tạo ra không khí không có bụi",2,"Sản xuất và đốt nhiên liệu có thể làm tăng ô nhiễm."],["Phát minh máy móc có thể thay đổi nghề nghiệp vì?","Nghề nào cũng biến mất ngay","Không liên quan kĩ năng","Không thay đổi sản xuất","Một số việc được tự động hóa, nhu cầu kĩ năng thay đổi",3,"Công nghệ thay đổi nhiệm vụ và nhu cầu kỹ năng, không làm mọi nghề biến mất."],["Khi so sánh trước và sau công nghiệp hóa nên dùng?","Nhiều chỉ tiêu và tư liệu theo thời gian","Một câu chuyện duy nhất","Số liệu không rõ nguồn","Chỉ ảnh minh họa",0,"Dữ liệu đa dạng và mốc thời gian giúp so sánh có cơ sở."],["Vì sao cách mạng công nghiệp không chỉ là phát minh máy móc?","Chỉ đổi tên máy","Nó làm thay đổi kinh tế, xã hội, đô thị và môi trường","Không liên quan con người","Chỉ diễn ra trong một ngày",1,"Đây là quá trình chuyển đổi rộng lớn về sản xuất và đời sống."],["Bài học khi đánh giá công nghệ hiện nay từ lịch sử công nghiệp?","Mọi công nghệ đều hoàn hảo","Không cần quản lí","Cân nhắc lợi ích, tác động xã hội và môi trường","Chỉ quan tâm tốc độ",2,"Đổi mới cần đánh giá lợi ích và hệ quả, có giải pháp quản lí."]]),status:'draft'},
  {lessonId:"hg9-history-doimoi",grade:9,strand:'history',title:"Việt Nam trong thời kì Đổi mới",questions:buildQuestions("hg9-history-doimoi",[["Đường lối Đổi mới được đề ra tại Đại hội VI năm?","1975","1980","1991","1986",3,"Đại hội VI diễn ra năm 1986, mở đầu công cuộc Đổi mới."],["Đổi mới trước hết tập trung vào lĩnh vực nào?","Kinh tế","Ngừng giáo dục","Đóng cửa giao lưu","Bỏ sản xuất",0,"Đổi mới tập trung chuyển biến kinh tế, sau đó mở rộng nhiều lĩnh vực."],["Một mục tiêu quan trọng của Đổi mới là?","Giảm sản xuất","Phát triển kinh tế, cải thiện đời sống","Ngừng giao thương","Không thay đổi quản lí",1,"Đổi mới nhằm phát triển kinh tế và nâng cao đời sống."],["Hội nhập kinh tế quốc tế thể hiện qua?","Tách khỏi thị trường","Không hợp tác","Mở rộng trao đổi, hợp tác và tham gia liên kết","Chỉ giao dịch nội bộ",2,"Hội nhập tăng cường quan hệ kinh tế với các nước và tổ chức."],["Việt Nam gia nhập ASEAN năm?","1986","1990","1995","2005",2,"Việt Nam gia nhập ASEAN năm 1995."],["Việt Nam gia nhập WTO năm?","2007","1995","2015","1986",0,"Việt Nam trở thành thành viên WTO năm 2007."],["Đổi mới làm thay đổi cơ cấu kinh tế theo hướng?","Chỉ nông nghiệp","Đa dạng ngành, tăng vai trò công nghiệp và dịch vụ","Không có dịch vụ","Chấm dứt trao đổi",1,"Cơ cấu kinh tế chuyển dịch, công nghiệp và dịch vụ phát triển."],["Một thách thức trong phát triển hiện nay là?","Không có chênh lệch","Không cần bảo vệ môi trường","Không cần kỹ năng","Chênh lệch phát triển, môi trường và chất lượng nguồn nhân lực",3,"Phát triển đặt ra các thách thức về công bằng, môi trường và nhân lực."],["Vì sao cần xem số liệu GDP cùng năm và cùng đơn vị?","Để so sánh có ý nghĩa","Để bỏ qua dữ liệu","Để tăng số liệu","Để tránh biểu đồ",0,"Đơn vị và thời gian thống nhất giúp so sánh đúng."],["Khi nhận xét thành tựu Đổi mới nên?","Chỉ dùng cảm xúc","Dùng dẫn chứng, chỉ tiêu và mốc thời gian","Chỉ nêu một ví dụ","Không so sánh",1,"Nhận xét cần dẫn chứng và bối cảnh."],["Tăng trưởng kinh tế có đồng nghĩa mọi người hưởng lợi giống nhau?","Có, luôn luôn","Không cần khảo sát","Không, cần xem phân phối, cơ hội và chỉ số xã hội","Chỉ phụ thuộc dân số",2,"Tăng trưởng không tự phản ánh mức phân phối lợi ích."],["Đổi mới và hội nhập có liên hệ gì?","Không liên quan","Hội nhập chỉ là du lịch","Đổi mới ngăn giao thương","Đổi mới tạo điều kiện mở rộng hợp tác và hội nhập",3,"Chính sách đổi mới góp phần mở rộng quan hệ và hội nhập."],["Nếu biểu đồ cho thấy tỉ trọng nông nghiệp giảm, có thể kết luận?","Cơ cấu có chuyển dịch; cần xem giá trị tuyệt đối và các ngành khác","Nông nghiệp biến mất","Sản lượng chắc chắn giảm","Không cần xem đơn vị",0,"Tỉ trọng thay đổi chưa đủ kết luận giá trị tuyệt đối giảm."],["Một đánh giá cân bằng về Đổi mới cần?","Chỉ nêu thành công","Xem thành tựu, hạn chế, thách thức và bối cảnh","Chỉ nêu khó khăn","Dùng tin không nguồn",1,"Đánh giá cân bằng xem cả mặt tích cực, hạn chế và bối cảnh."],["Khi dùng thông tin lịch sử gần đây, nguồn nên ưu tiên?","Bài đăng không rõ tác giả","Tin đồn","Nguồn chính thống, có ngày và dữ liệu kiểm chứng","Nội dung không dẫn chứng",2,"Nguồn chính thống và có thể kiểm chứng giúp giảm sai lệch."]]),status:'draft'},

  {lessonId:"g6-history-01",grade:6,strand:'history',title:"Lịch sử và cuộc sống",questions:buildQuestions("g6-history-01",[
    ["Lịch sử được hiểu phù hợp nhất là gì?","Những gì đã diễn ra trong quá khứ của xã hội loài người","Những dự đoán về tương lai","Chỉ các câu chuyện thần thoại","Danh sách ngày nghỉ",0,"Lịch sử nghiên cứu những gì đã diễn ra trong quá khứ của con người và xã hội."],
    ["Học lịch sử giúp chúng ta hiểu điều gì?","Chỉ ghi nhớ tên nhân vật","Cội nguồn, quá trình hình thành và thay đổi của cộng đồng","Dự báo chính xác mọi việc","Thay thế các môn học khác",1,"Lịch sử giúp nhận thức cội nguồn và quá trình phát triển của con người, cộng đồng."],
    ["Đâu là ví dụ về dấu tích quá khứ có thể tìm hiểu lịch sử?","Một kế hoạch chưa thực hiện","Một dự báo thời tiết","Một ngôi đình cổ ở địa phương","Một trò chơi mới phát hành",2,"Di tích và công trình cổ có thể lưu giữ thông tin về đời sống quá khứ."],
    ["Khi tìm hiểu lịch sử gia đình, nguồn thông tin nào có thể hữu ích?","Chỉ lời đồn chưa kiểm chứng","Một quảng cáo","Một dự đoán","Ảnh cũ, giấy tờ và lời kể của người thân",3,"Có thể đối chiếu ảnh, giấy tờ và lời kể để tìm hiểu lịch sử gia đình."],
    ["Vì sao cần học lịch sử địa phương?","Để hiểu sự hình thành và những thay đổi nơi mình sống","Để chỉ học tên đường","Để thay thế bản đồ","Để không cần tìm hiểu nơi khác",0,"Lịch sử địa phương giúp hiểu cộng đồng và nơi chốn trong mối liên hệ với lịch sử rộng hơn."],
    ["Một câu chuyện được kể lại nhiều lần có tự động trở thành sự thật lịch sử không?","Có, nếu kể hấp dẫn","Không, cần kiểm tra và đối chiếu chứng cứ","Có, nếu người kể nổi tiếng","Không cần xem xét",1,"Nhận định lịch sử cần dựa trên chứng cứ và kiểm tra nguồn tin."],
    ["Khi học một sự kiện, vì sao cần đặt nó vào bối cảnh?","Để bỏ qua nguyên nhân","Để chỉ nhớ ngày tháng","Để hiểu điều kiện, nguyên nhân và tác động của sự kiện","Để biến sự kiện thành truyền thuyết",2,"Bối cảnh giúp giải thích vì sao sự kiện diễn ra và ảnh hưởng của nó."],
    ["Thái độ phù hợp khi tiếp cận một thông tin lịch sử mới là gì?","Tin ngay mọi nội dung","Chỉ chọn điều mình thích","Bỏ qua nguồn dẫn","Đặt câu hỏi và kiểm tra nguồn tư liệu",3,"Tư duy lịch sử cần sự tò mò, thận trọng và kiểm chứng."],
    ["Một bảo tàng trưng bày công cụ lao động cổ. Hiện vật đó giúp tìm hiểu điều gì?","Cách con người từng lao động và sinh hoạt","Dự báo giá cả ngày mai","Thời tiết tương lai","Luật giao thông hiện nay",0,"Công cụ lao động cung cấp manh mối về kĩ thuật và đời sống trong quá khứ."],
    ["Điều nào thể hiện việc vận dụng hiểu biết lịch sử vào hiện tại?","Chỉ chép lại sách","Rút kinh nghiệm từ cách cộng đồng ứng phó khó khăn trước đây","Không quan tâm di sản","Đoán sự kiện chưa xảy ra",1,"Lịch sử có thể cung cấp kinh nghiệm để suy nghĩ và lựa chọn trong hiện tại."],
    ["Khi hai lời kể về cùng một việc không giống nhau, nên làm gì?","Chọn lời kể dài hơn","Chọn lời kể đầu tiên","Tìm thêm tư liệu và so sánh hoàn cảnh người kể","Kết luận cả hai đều sai",2,"Đối chiếu nhiều nguồn và bối cảnh giúp đánh giá thông tin cân bằng hơn."],
    ["Một địa phương phục dựng lễ hội truyền thống dựa trên tư liệu. Việc này góp phần gì?","Xóa bỏ mọi dấu tích cũ","Chỉ tạo hoạt động giải trí","Thay đổi lịch sử đã xảy ra","Gìn giữ và giới thiệu di sản văn hóa",3,"Nghiên cứu và phục dựng có căn cứ giúp bảo tồn, giới thiệu di sản."],
    ["Một học sinh muốn tìm hiểu lịch sử trường học. Bước đầu phù hợp là gì?","Tìm hồ sơ, ảnh, kỉ yếu và hỏi người từng học hoặc công tác tại trường","Tự đặt ra ngày thành lập","Chỉ dựa vào một bình luận mạng","Bỏ qua mốc thời gian",0,"Nhiều loại tư liệu giúp kiểm tra chéo lịch sử của trường."],
    ["Vì sao không nên chỉ dựa vào một nguồn khi giải thích sự kiện?","Một nguồn luôn sai","Nhiều nguồn giúp kiểm tra chéo và nhận ra góc nhìn khác nhau","Nguồn thứ hai luôn đúng","Để kéo dài bài viết",1,"Đối chiếu giúp giảm nguy cơ sai lệch và hiểu sự kiện đầy đủ hơn."],
    ["Một nhóm học sinh giới thiệu di tích ở địa phương. Cách trình bày có căn cứ nhất là gì?","Chỉ kể cảm xúc","Dùng thông tin không ghi xuất xứ","Nêu vị trí, đặc điểm, tư liệu tham khảo và điều đã kiểm chứng","Khẳng định điều chưa rõ",2,"Giới thiệu lịch sử cần phân biệt thông tin đã kiểm chứng với điều còn cần tìm hiểu."]
  ]),status:'draft'},

 {lessonId:"g6-history-02",grade:6,strand:'history',title:"Dựa vào đâu để biết và phục dựng lại lịch sử?",questions:buildQuestions("g6-history-02",[
    ["Tư liệu lịch sử là gì?","Những dấu tích và thông tin còn lại từ quá khứ","Mọi dự đoán về tương lai","Chỉ những câu chuyện hư cấu","Chỉ các văn bản mới viết",0,"Tư liệu lịch sử là dấu tích, tài liệu và thông tin giúp con người tìm hiểu quá khứ."],
    ["Trong khai quật khảo cổ, vật dụng bằng đá còn nguyên dấu chế tác được xếp vào nhóm nào?","Tư liệu truyền miệng","Tư liệu hiện vật","Tư liệu thống kê","Tư liệu dự báo",1,"Công cụ bằng đá còn lại từ quá khứ là tư liệu hiện vật."],
    ["Đâu là tư liệu chữ viết?","Một chiếc bình gốm","Một lời kể chưa ghi lại","Một tấm bia có khắc văn bản","Một bức tường thành",2,"Văn bản trên bia là tư liệu chữ viết."],
    ["Truyện kể dân gian về một nhân vật xưa thuộc loại tư liệu nào?","Hiện vật","Bản đồ tự nhiên","Tư liệu số liệu","Tư liệu truyền miệng",3,"Thông tin được lưu truyền qua lời kể thuộc tư liệu truyền miệng."],
    ["Ảnh chụp một sự kiện lịch sử được xếp vào nhóm tư liệu nào?","Tư liệu hình ảnh","Tư liệu địa chất","Tư liệu khí hậu","Tư liệu dự báo",0,"Hình ảnh ghi lại sự kiện là một dạng tư liệu hình ảnh."],
    ["Khi tìm hiểu một hiện vật khảo cổ, thông tin nào cần chú ý?","Màu yêu thích của người xem","Nơi phát hiện, niên đại và bối cảnh khai quật","Giá bán trên mạng","Kích thước màn hình",1,"Xuất xứ và bối cảnh phát hiện giúp xác định giá trị lịch sử của hiện vật."],
    ["Vì sao cần xác định nguồn gốc của một tư liệu?","Để trang trí bài học","Để tăng số trang","Để đánh giá hoàn cảnh hình thành và độ tin cậy","Để thay đổi nội dung tư liệu",2,"Nguồn gốc cho biết ai tạo lập, khi nào và trong hoàn cảnh nào."],
    ["Một cuốn nhật kí được viết trong thời gian sự kiện diễn ra có thể cung cấp điều gì?","Mọi thông tin đều chắc chắn chính xác","Chỉ thông tin về thời tiết","Không có giá trị lịch sử","Góc nhìn của người viết trong bối cảnh đương thời",3,"Nhật kí có thể phản ánh trải nghiệm và góc nhìn của người viết, nhưng vẫn cần đối chiếu."],
    ["Tại sao một lời kể truyền miệng có thể thay đổi theo thời gian?","Do người kể có thể nhớ khác, thêm bớt hoặc diễn giải","Vì mọi lời kể đều được in lại","Vì lời kể không liên quan quá khứ","Vì thời gian làm mất mọi ngôn ngữ",0,"Trí nhớ và quá trình truyền kể có thể làm nội dung thay đổi."],
    ["Khi hai nguồn tư liệu có thông tin khác nhau, nên làm gì?","Chọn nguồn có nhiều chữ hơn","Đối chiếu xuất xứ, thời điểm và các chứng cứ độc lập","Tin nguồn xuất hiện đầu tiên","Bỏ qua tất cả",1,"Đối chiếu nhiều nguồn và đánh giá bối cảnh giúp kiểm tra thông tin."],
    ["Tư liệu nào thường giúp nghiên cứu chữ khắc trên một công trình cổ?","Bản tin dự báo","Bảng giá hiện nay","Văn bia hoặc dòng chữ khắc còn lưu lại","Bản đồ thời tiết",2,"Văn bia và chữ khắc là tư liệu chữ viết trực tiếp trên di tích."],
    ["Một hiện vật được tìm thấy trong tầng văn hóa khảo cổ có thể giúp nhà nghiên cứu tìm hiểu điều gì?","Dự đoán chính xác tương lai","Xác định sở thích của người khai quật","Tính khoảng cách giữa các hành tinh","Đời sống và hoạt động của cư dân trong quá khứ",3,"Hiện vật trong bối cảnh khảo cổ cung cấp chứng cứ về sinh hoạt và hoạt động xưa."],
    ["Muốn tìm hiểu lịch sử một ngôi trường, nhóm học sinh nên kết hợp nguồn nào?","Hồ sơ lưu trữ, ảnh cũ và lời kể của cựu giáo viên","Chỉ một bài đăng không rõ tác giả","Các tin đồn không có căn cứ","Thông tin về một trường khác",0,"Kết hợp hồ sơ, hình ảnh và lời kể giúp kiểm tra chéo thông tin."],
    ["Vì sao cần đặt tư liệu vào bối cảnh lịch sử?","Để bỏ qua thời gian","Để hiểu điều kiện, mục đích và hoàn cảnh tạo ra tư liệu","Để mọi tư liệu có cùng ý nghĩa","Để thay đổi niên đại",1,"Bối cảnh giúp giải thích đúng ý nghĩa của tư liệu, tránh áp đặt cách hiểu hiện nay."],
    ["Một nhóm chỉ có một bức ảnh không rõ nơi chụp để kết luận về một sự kiện. Cách làm khoa học hơn là gì?","Khẳng định ngay kết luận","Tự suy ra tên người trong ảnh","Tìm thêm nguồn xác thực thời gian, địa điểm và đối chiếu chứng cứ","Xóa bỏ mọi tư liệu khác",2,"Một ảnh đơn lẻ thiếu xuất xứ chưa đủ; cần xác minh và đối chiếu nguồn khác."],
 ]),status:'draft'},

  {lessonId:'g6-history-03',grade:6,strand:'history',title:'Thời gian trong lịch sử',questions:buildQuestions('g6-history-03',[
    ['Trong lịch sử, thời gian giúp xác định điều gì?','Thời điểm và trình tự diễn ra của sự kiện','Màu sắc hiện vật','Kích thước bản đồ','Nhiệt độ không khí',0,'Mốc thời gian cho biết khi nào sự kiện diễn ra và giúp sắp xếp trình tự.'],
    ['Dương lịch được tính chủ yếu dựa trên chu kì nào?','Mặt Trăng quay quanh Trái Đất','Trái Đất chuyển động quanh Mặt Trời','Thủy triều','Sự thay đổi mùa mưa',1,'Dương lịch dựa trên chu kì Trái Đất chuyển động quanh Mặt Trời.'],
    ['Âm lịch truyền thống chủ yếu dựa vào chu kì nào?','Sự tự quay của Trái Đất','Chu kì nhật thực','Tuần trăng của Mặt Trăng','Sự chuyển động của sao Hỏa',2,'Âm lịch truyền thống căn cứ vào chu kì tuần trăng.'],
    ['Công nguyên được quy ước lấy mốc trung tâm là sự kiện nào?','Thành lập nhà nước Văn Lang','Xây dựng Kim tự tháp','Phát minh chữ viết','Năm được quy ước gắn với sự ra đời của Chúa Giê-su',3,'Công nguyên lấy mốc quy ước gắn với năm sinh của Chúa Giê-su.'],
    ['Những năm trước Công nguyên được tính theo chiều nào?','Càng xa mốc Công nguyên thì số năm càng lớn','Càng gần hiện tại thì số năm càng lớn','Luôn tăng từ 1 đến vô hạn về phía hiện tại','Không thể sắp xếp',0,'Năm trước Công nguyên giảm dần khi tiến gần đến mốc Công nguyên.'],
    ['Một thế kỉ có bao nhiêu năm?','10 năm','100 năm','500 năm','1.000 năm',1,'Một thế kỉ gồm 100 năm.'],
    ['Năm 2026 thuộc thế kỉ nào?','Thế kỉ XX','Thế kỉ XXI','Thế kỉ XIX','Thế kỉ XXII',1,'Các năm từ 2001 đến 2100 thuộc thế kỉ XXI.'],
    ['Năm 1453 thuộc thế kỉ nào?','Thế kỉ XIII','Thế kỉ XIV','Thế kỉ XV','Thế kỉ XVI',2,'Các năm 1401–1500 thuộc thế kỉ XV.'],
    ['Năm 938 thuộc thế kỉ nào?','Thế kỉ VIII','Thế kỉ IX','Thế kỉ X','Thế kỉ XI',1,'Các năm 901–1000 thuộc thế kỉ X.'],
    ['Trên trục thời gian, sự kiện nằm bên trái thường xảy ra như thế nào so với sự kiện bên phải?','Muộn hơn','Cùng lúc trong mọi trường hợp','Không xác định được','Sớm hơn',3,'Trục thời gian thường sắp xếp các mốc từ quá khứ đến hiện tại theo chiều trái sang phải.'],
    ['Từ năm 1200 đến năm 1250 cách nhau bao nhiêu năm?','50 năm','100 năm','25 năm','150 năm',0,'Lấy 1250 trừ 1200 được 50 năm.'],
    ['Khi ghi một sự kiện năm 40 trước Công nguyên, cách viết nào phù hợp?','Năm 40','Năm 40 sau Công nguyên','Năm 40 TCN','Thế kỉ 40',2,'TCN là viết tắt của trước Công nguyên.'],
    ['Một sự kiện xảy ra năm 1010 và sự kiện khác năm 1015. Sự kiện nào diễn ra trước?','Sự kiện năm 1015','Hai sự kiện cùng lúc','Không thể biết','Sự kiện năm 1010',3,'Năm 1010 sớm hơn năm 1015.'],
    ['Khi so sánh hai sự kiện ở hai thời kì khác nhau, cần làm gì?','Đưa các mốc về cùng hệ quy chiếu thời gian và xác định rõ TCN/CN','Bỏ qua niên đại','Chỉ dựa vào độ dài tên sự kiện','Đổi tùy ý mốc năm',0,'Cần xác định đúng hệ tính năm và mốc trước/sau Công nguyên để tránh nhầm lẫn.'],
    ['Sự kiện A diễn ra năm 200 TCN, sự kiện B diễn ra năm 150 TCN. Kết luận nào đúng?','A diễn ra sau B','B diễn ra sau A','Hai sự kiện cách nhau 350 năm','Không thể xác định thứ tự',1,'Trong thời kì trước Công nguyên, năm 200 TCN sớm hơn năm 150 TCN.']
  ]),status:'draft'},



  {lessonId:'g6-history-04',grade:6,strand:'history',title:'Nguồn gốc loài người',questions:buildQuestions('g6-history-04',[
    ['Những ngành khoa học nào góp phần nghiên cứu nguồn gốc loài người?','Khảo cổ học và nhân học','Thiên văn học và khí tượng học','Hải dương học và thực vật học','Địa chính trị học',0,'Khảo cổ học nghiên cứu di tích, di vật; nhân học nghiên cứu con người và quá trình tiến hóa.'],
    ['Theo các bằng chứng khoa học hiện nay, châu lục nào có những dấu tích sớm quan trọng về người cổ?','Châu Âu','Châu Phi','Châu Đại Dương','Châu Nam Cực',1,'Nhiều hóa thạch người cổ sớm được phát hiện tại châu Phi.'],
    ['Hóa thạch có giá trị gì khi nghiên cứu nguồn gốc loài người?','Cho biết chính xác mọi suy nghĩ của người cổ','Thay thế hoàn toàn việc nghiên cứu công cụ','Cung cấp bằng chứng về đặc điểm cơ thể và niên đại tương đối','Chỉ phản ánh khí hậu hiện nay',2,'Hóa thạch giúp các nhà khoa học tìm hiểu đặc điểm sinh học và lịch sử tiến hóa.'],
    ['Một đặc điểm quan trọng trong quá trình tiến hóa của người là gì?','Sống hoàn toàn dưới nước','Có thể bay','Không cần hợp tác','Đi bằng hai chân',3,'Đi thẳng bằng hai chân là một đặc điểm quan trọng trong quá trình tiến hóa của loài người.'],
    ['Công cụ lao động bằng đá của người nguyên thủy cho thấy điều gì?','Con người đã biết lựa chọn và ghè đẽo vật liệu để đáp ứng nhu cầu','Con người đã sử dụng máy hơi nước','Con người đã có chữ viết hoàn chỉnh','Con người đã sản xuất đồ điện',0,'Công cụ đá phản ánh khả năng chế tác và sử dụng vật liệu tự nhiên.'],
    ['Việc biết sử dụng lửa đem lại lợi ích nào cho người nguyên thủy?','Chỉ dùng để trang trí','Sưởi ấm, nấu thức ăn và xua đuổi thú dữ','Làm thay đổi quỹ đạo Trái Đất','Thay thế mọi công cụ lao động',1,'Lửa giúp sưởi ấm, nấu chín thức ăn, chiếu sáng và bảo vệ con người.'],
    ['Vì sao sự hợp tác có ý nghĩa đối với cộng đồng người nguyên thủy?','Làm cho việc kiếm sống không còn cần thiết','Khiến mọi người sống tách biệt','Giúp cùng săn bắt, hái lượm và bảo vệ nhau','Làm mất khả năng truyền kinh nghiệm',2,'Hợp tác giúp tăng hiệu quả kiếm sống và khả năng thích nghi với môi trường.'],
    ['Bằng chứng nào sau đây là di vật do con người tạo ra?','Một lớp tro núi lửa tự nhiên','Một chiếc lá hóa thạch','Một hòn đá chưa có dấu vết tác động','Mảnh công cụ đá có vết ghè đẽo',3,'Dấu vết chế tác cho thấy công cụ đá là sản phẩm hoạt động của con người.'],
    ['Khi phát hiện một bộ xương hóa thạch, nhà nghiên cứu cần làm gì?','Ghi nhận vị trí, tầng đất và phân tích mẫu theo phương pháp khoa học','Tự ý di chuyển rồi bỏ qua vị trí','Dựa vào lời đồn để xác định tuổi','Kết luận ngay mà không đối chiếu',0,'Bối cảnh phát hiện và phương pháp phân tích rất quan trọng để đánh giá chứng cứ.'],
    ['Quá trình con người di cư ra khỏi châu Phi có ý nghĩa nào?','Làm cho con người biến mất khỏi châu Phi','Góp phần đưa người hiện đại đến cư trú ở nhiều khu vực trên thế giới','Khiến các châu lục dịch chuyển','Xóa bỏ mọi khác biệt môi trường',1,'Các đợt di cư góp phần mở rộng phạm vi cư trú của người hiện đại.'],
    ['Tại sao không nên xem một hiện vật đơn lẻ là bằng chứng đủ để kết luận toàn bộ lịch sử tiến hóa?','Vì hiện vật không bao giờ có giá trị','Vì mọi hiện vật đều giống nhau','Vì cần đặt hiện vật trong bối cảnh và đối chiếu nhiều loại chứng cứ','Vì chỉ truyền thuyết mới đáng tin',2,'Kết luận khoa học cần nhiều bằng chứng độc lập và bối cảnh khảo cổ rõ ràng.'],
    ['Một nhóm học sinh tìm thấy mảnh đá có cạnh sắc trong khu vực khảo cổ. Muốn xác định đó là công cụ, các em nên chú ý điều gì?','Màu áo người tìm thấy','Dự đoán tùy ý về chủ nhân','Chỉ dựa vào kích thước lớn hay nhỏ','Dấu vết ghè đẽo, hình dáng sử dụng và bối cảnh phát hiện',3,'Dấu vết chế tác và bối cảnh giúp phân biệt công cụ với đá tự nhiên.'],
    ['Vì sao việc truyền kinh nghiệm giữa các thành viên giúp cộng đồng người cổ tồn tại tốt hơn?','Kinh nghiệm được chia sẻ giúp cải thiện cách kiếm sống và tránh nguy hiểm','Mọi người không cần quan sát thiên nhiên','Nó làm cho môi trường không thay đổi','Nó khiến công cụ không còn cần thiết',0,'Học hỏi và truyền kinh nghiệm giúp cộng đồng thích nghi hiệu quả hơn.'],
    ['Khi so sánh hai mẫu hóa thạch ở hai địa điểm, thông tin nào cần được xem xét cùng nhau?','Màu sắc ảnh chụp','Đặc điểm mẫu, niên đại, tầng địa chất và bối cảnh khai quật','Sở thích của người sưu tầm','Tên gọi do người xem tự đặt',1,'So sánh khoa học cần dữ liệu về mẫu và bối cảnh địa chất, khảo cổ.'],
    ['Một phát hiện mới có niên đại sớm hơn mẫu đã biết trước đây. Cách ứng xử khoa học phù hợp là gì?','Bác bỏ ngay mọi nghiên cứu cũ','Giữ nguyên kết luận bất kể chứng cứ','Kiểm tra phương pháp định tuổi, đối chiếu chứng cứ và cập nhật nhận thức nếu đủ căn cứ','Khẳng định phát hiện mới đúng mà không kiểm tra',2,'Tri thức khoa học được điều chỉnh khi có chứng cứ mới được kiểm chứng.']
  ]),status:'draft'},


  {lessonId:'g6-history-05',grade:6,strand:'history',title:'Xã hội nguyên thủy',questions:buildQuestions('g6-history-05',[
    ['Hoạt động kiếm sống chủ yếu của người nguyên thủy thời kì đầu là gì?','Săn bắt và hái lượm','Buôn bán đường biển','Sản xuất công nghiệp','Trồng cây công nghiệp quy mô lớn',0,'Săn bắt và hái lượm là cách kiếm sống phổ biến của cộng đồng người nguyên thủy thời kì đầu.'],
    ['Công cụ đá ghè đẽo thường có đặc điểm nào?','Được làm bằng nhựa','Một mặt hoặc nhiều cạnh được ghè để tạo hình sử dụng','Có động cơ','Được đúc bằng sắt',1,'Người nguyên thủy ghè đá để tạo cạnh sắc phục vụ lao động.'],
    ['Công cụ đá mài thể hiện bước tiến nào?','Con người không còn lao động','Không biết chọn vật liệu','Kĩ thuật chế tác công cụ tiến bộ hơn','Đã có máy móc tự động',2,'Mài đá giúp công cụ có hình dáng và bề mặt phù hợp hơn với mục đích sử dụng.'],
    ['Việc biết trồng trọt và chăn nuôi giúp con người thay đổi điều gì?','Phải di chuyển liên tục hơn','Không cần tổ chức cộng đồng','Không còn phụ thuộc tự nhiên','Tạo ra nguồn lương thực chủ động và ổn định hơn',3,'Sản xuất nông nghiệp giúp con người chủ động hơn trong việc tạo ra thức ăn.'],
    ['Đồ gốm xuất hiện có thể gắn với nhu cầu nào?','Chế tạo vật đựng, nấu và bảo quản thức ăn','Làm phương tiện bay','In sách hàng loạt','Truyền tin bằng điện',0,'Đồ gốm phục vụ chứa đựng, chế biến và bảo quản thực phẩm.'],
    ['Khi con người biết định cư lâu dài, điều gì thường diễn ra?','Mọi hoạt động sản xuất chấm dứt','Xuất hiện nơi cư trú ổn định hơn','Không còn quan hệ cộng đồng','Tất cả chuyển sang sống trên thuyền',1,'Trồng trọt và chăn nuôi góp phần hình thành các khu cư trú ổn định.'],
    ['Vì sao lao động tập thể quan trọng đối với người nguyên thủy?','Làm cho thức ăn tự xuất hiện','Thay thế hoàn toàn công cụ','Giúp phối hợp kiếm sống và bảo vệ cộng đồng','Khiến môi trường không ảnh hưởng đến con người',2,'Hợp tác giúp chia sẻ công việc và tăng khả năng tồn tại.'],
    ['Sự xuất hiện của công cụ kim loại tạo điều kiện nào?','Không cần khai thác tài nguyên','Chấm dứt mọi hoạt động thủ công','Không thay đổi năng suất','Nâng cao hiệu quả lao động và mở rộng sản xuất',3,'Công cụ kim loại thường bền và hiệu quả hơn nhiều công cụ đá trước đó.'],
    ['Đâu là ví dụ về hoạt động sản xuất của cư dân nguyên thủy thời kì sau?','Trồng cây lương thực và nuôi gia súc','Săn bắt voi ma mút bằng súng','Sản xuất máy tính','Khai thác dầu bằng giàn khoan hiện đại',0,'Trồng trọt và chăn nuôi đánh dấu bước chuyển quan trọng trong cách kiếm sống.'],
    ['Việc phát hiện dấu tích bếp lửa tại nơi cư trú cổ có thể cho biết điều gì?','Người cổ đã có điện','Con người biết sử dụng lửa trong sinh hoạt','Họ đã dùng bếp gas','Họ đã có nhà máy',1,'Bếp lửa là chứng cứ về việc sử dụng lửa trong đời sống.'],
    ['Tại sao sản xuất tạo ra thay đổi trong tổ chức xã hội?','Vì sản xuất không liên quan đến đời sống','Vì mọi người sống tách biệt hơn','Vì cách tạo ra và phân phối sản phẩm ảnh hưởng quan hệ giữa các thành viên','Vì công cụ không còn quan trọng',2,'Sự thay đổi phương thức sản xuất tác động đến phân công lao động và quan hệ xã hội.'],
    ['Một di chỉ có nhiều công cụ đá mài, dấu tích hạt cây và xương động vật nuôi. Nhận định nào có căn cứ nhất?','Cư dân chỉ sống bằng săn bắt thú lớn','Đã có nhà máy luyện thép','Chắc chắn có chữ viết','Có thể cư dân đã biết trồng trọt và chăn nuôi, cần tiếp tục phân tích chứng cứ',3,'Nhiều loại di vật kết hợp giúp đưa ra giả thuyết về hoạt động sản xuất, nhưng cần kiểm chứng.'],
    ['Khi so sánh hai cộng đồng nguyên thủy, yếu tố nào giúp nhận biết trình độ sản xuất?','Loại công cụ, dấu tích cư trú và bằng chứng về trồng trọt/chăn nuôi','Màu sắc hiện đại của bản đồ','Số lượng sách in','Tên gọi do người nghiên cứu tự đặt',0,'Công cụ và dấu tích kinh tế là các nguồn chứng cứ quan trọng.'],
    ['Một nhóm tìm thấy công cụ đá mài và hạt ngũ cốc cháy trong cùng tầng văn hóa. Cách giải thích nào hợp lí?','Chắc chắn họ đã dùng máy cày','Có thể có hoạt động chế biến ngũ cốc; cần xác định niên đại và bối cảnh','Không thể liên hệ hai phát hiện','Hạt ngũ cốc chứng minh có chữ viết',1,'Hai loại chứng cứ gợi ý hoạt động chế biến thực phẩm nhưng cần kiểm tra bối cảnh khảo cổ.'],
    ['Vì sao cần tránh áp dụng nguyên xi khái niệm xã hội hiện đại khi mô tả cộng đồng nguyên thủy?','Vì quá khứ không thể nghiên cứu','Vì mọi cộng đồng đều giống xã hội hiện đại','Vì điều kiện sản xuất và quan hệ xã hội thời nguyên thủy khác xa hiện nay','Vì chỉ có truyền thuyết mới mô tả xã hội',2,'Cần đặt đời sống người nguyên thủy trong điều kiện lịch sử cụ thể của thời đại đó.']
  ]),status:'draft'},


  {lessonId:'g6-history-06',grade:6,strand:'history',title:'Sự chuyển biến và phân hóa của xã hội nguyên thủy',questions:buildQuestions('g6-history-06',[
    ['Việc sử dụng công cụ kim loại có tác động quan trọng nào đến sản xuất?','Nâng cao năng suất lao động','Làm mất hoàn toàn nhu cầu lao động','Khiến con người không cần trao đổi sản phẩm','Chấm dứt trồng trọt',0,'Công cụ kim loại giúp khai phá đất đai và chế tác hiệu quả hơn, góp phần tăng năng suất.'],
    ['Sản phẩm dư thừa là gì?','Sản phẩm không thể sử dụng','Phần sản phẩm còn lại sau khi đáp ứng nhu cầu cần thiết','Mọi sản phẩm bị hư hỏng','Sản phẩm chỉ dùng để trao đổi quốc tế',1,'Sản phẩm dư thừa xuất hiện khi sản xuất tạo ra nhiều hơn mức tiêu dùng trực tiếp.'],
    ['Điều kiện nào góp phần làm xuất hiện sản phẩm dư thừa?','Không có công cụ lao động','Con người ngừng sản xuất','Năng suất lao động tăng và sản xuất ổn định hơn','Mọi người sống biệt lập',2,'Công cụ tiến bộ và sản xuất phát triển có thể tạo ra sản phẩm vượt nhu cầu trước mắt.'],
    ['Sự phân hóa giàu nghèo trong cộng đồng nguyên thủy gắn với hiện tượng nào?','Mọi người có tài sản hoàn toàn giống nhau','Không có sản phẩm lao động','Không có hoạt động sản xuất','Một số người tích lũy được nhiều của cải hơn người khác',3,'Khả năng tích lũy của cải không đồng đều góp phần làm nảy sinh phân hóa xã hội.'],
    ['Yếu tố nào góp phần làm thay đổi quan hệ cộng đồng nguyên thủy?','Sự tích lũy tài sản và phân hóa sản phẩm','Sự thay đổi màu sắc đất','Việc đổi tên các dòng sông','Sự xuất hiện bản đồ hiện đại',0,'Khi của cải được tích lũy không đồng đều, quan hệ giữa các thành viên cũng biến đổi.'],
    ['Vì sao công cụ kim loại có thể thúc đẩy phân công lao động?','Vì không còn nghề thủ công','Vì sản xuất đa dạng và hiệu quả hơn, tạo điều kiện chuyên môn hóa','Vì mọi người chỉ làm một việc giống nhau','Vì công cụ kim loại không cần người sử dụng',1,'Sản xuất phát triển tạo điều kiện cho các hoạt động và nghề nghiệp chuyên biệt hơn.'],
    ['Sự phân hóa xã hội nguyên thủy thể hiện rõ nhất ở khía cạnh nào?','Mọi gia đình có cùng lượng của cải','Mọi người không có quan hệ cộng đồng','Chênh lệch về tài sản và vị thế giữa các thành viên','Tất cả cùng di cư một lúc',2,'Sự khác biệt về của cải và quyền lợi là biểu hiện của phân hóa xã hội.'],
    ['Sự tan rã của xã hội nguyên thủy có liên quan đến quá trình nào?','Sự biến mất của mọi công cụ','Sự chấm dứt hoạt động sản xuất','Sự hình thành đại dương mới','Sự xuất hiện xã hội có giai cấp và nhà nước ở một số khu vực',3,'Biến đổi kinh tế và phân hóa xã hội góp phần dẫn đến xã hội có giai cấp, nhà nước.'],
    ['Nhận định nào đúng về mối quan hệ giữa năng suất lao động và sản phẩm dư thừa?','Năng suất tăng có thể tạo điều kiện xuất hiện sản phẩm dư thừa','Năng suất tăng luôn làm sản phẩm giảm','Hai yếu tố không liên quan','Sản phẩm dư thừa chỉ có khi không sản xuất',0,'Khi năng suất tăng, sản phẩm có thể vượt nhu cầu tiêu dùng trực tiếp.'],
    ['Tại sao không thể giải thích sự tan rã xã hội nguyên thủy chỉ bằng một nguyên nhân duy nhất?','Vì lịch sử không có nguyên nhân','Vì đây là quá trình liên quan nhiều biến đổi kinh tế và xã hội','Vì mọi khu vực đều thay đổi cùng một ngày','Vì công cụ không ảnh hưởng đời sống',1,'Đây là quá trình lâu dài, chịu tác động của sản xuất, của cải, phân công lao động và quan hệ xã hội.'],
    ['Một cộng đồng bắt đầu tích lũy lương thực và công cụ với mức độ khác nhau giữa các hộ. Điều này có thể dẫn tới điều gì?','Mọi khác biệt tự động biến mất','Không có thay đổi trong quan hệ xã hội','Sự chênh lệch về của cải giữa các hộ','Cộng đồng không còn cần sản xuất',2,'Tích lũy không đồng đều có thể tạo ra chênh lệch tài sản.'],
    ['Khi tìm hiểu sự phân hóa xã hội, loại chứng cứ nào có ích?','Chỉ các câu chuyện hiện đại','Màu sắc bản đồ hành chính','Ý kiến không có nguồn','Di vật, mộ táng, dấu tích cư trú và công cụ trong bối cảnh khảo cổ',3,'Nhiều loại chứng cứ khảo cổ có thể phản ánh chênh lệch tài sản và địa vị.'],
    ['Nếu một khu mộ có đồ tùy táng phong phú hơn hẳn các khu mộ khác, nhà nghiên cứu nên làm gì?','Đối chiếu nhiều mộ táng và bối cảnh trước khi đánh giá sự phân hóa','Kết luận ngay người đó là vua','Bỏ qua niên đại','Cho rằng mọi ngôi mộ đều cùng địa vị',0,'Cần so sánh hệ thống và xét bối cảnh để tránh kết luận vội vàng.'],
    ['Vì sao sự phát triển của luyện kim có thể làm thay đổi tổ chức sản xuất?','Vì kim loại chỉ dùng làm đồ trang sức','Vì cần nguyên liệu, kĩ năng và lao động chuyên biệt hơn','Vì không cần trao đổi nguyên liệu','Vì sản xuất kim loại không cần kiến thức',1,'Luyện kim đòi hỏi kĩ thuật và lao động chuyên môn, thúc đẩy phân công.'],
    ['Kết luận nào phản ánh đúng tính không đồng đều của quá trình chuyển biến xã hội nguyên thủy?','Mọi nơi đều hình thành nhà nước cùng một thời điểm','Mọi cộng đồng đều có cùng công cụ','Các khu vực có nhịp độ và con đường biến đổi khác nhau','Không có nơi nào xuất hiện phân hóa',2,'Điều kiện tự nhiên, kinh tế và lịch sử khác nhau khiến quá trình biến đổi không đồng đều.']
  ]),status:'draft'},


  {lessonId:'g6-history-07',grade:6,strand:'history',title:'Ai Cập và Lưỡng Hà cổ đại',questions:buildQuestions('g6-history-07',[
    ['Nền văn minh Ai Cập cổ đại hình thành chủ yếu bên lưu vực con sông nào?','Sông Nin','Sông Hoàng Hà','Sông Ấn','Sông Đa-nuýp',0,'Sông Nin cung cấp nước và phù sa, tạo điều kiện cho nông nghiệp Ai Cập.'],
    ['Lưỡng Hà cổ đại nằm giữa hai con sông nào?','Sông Nin và sông Hằng','Sông Ti-grơ và sông Ơ-phơ-rát','Sông Hoàng Hà và Trường Giang','Sông Ấn và sông Hằng',1,'Tên gọi Lưỡng Hà gắn với vùng đất giữa hai sông Ti-grơ và Ơ-phơ-rát.'],
    ['Công trình kiến trúc nổi tiếng gắn với Ai Cập cổ đại là gì?','Đấu trường Cô-li-dê','Vạn Lý Trường Thành','Kim tự tháp','Đền Pác-tê-nông',2,'Kim tự tháp là công trình kiến trúc tiêu biểu của Ai Cập cổ đại.'],
    ['Chữ viết tiêu biểu của cư dân Ai Cập cổ đại là gì?','Chữ hình nêm','Chữ La-tinh','Chữ Phạn','Chữ tượng hình',3,'Người Ai Cập sử dụng chữ tượng hình để ghi chép.'],
    ['Chữ viết tiêu biểu của cư dân Lưỡng Hà là gì?','Chữ hình nêm','Chữ tượng hình Ai Cập','Chữ Hán giản thể','Chữ Quốc ngữ',0,'Chữ hình nêm được khắc trên các bảng đất sét.'],
    ['Bộ luật Ha-mu-ra-bi gắn với nền văn minh nào?','Ai Cập','Lưỡng Hà','Hy Lạp','La Mã',1,'Ha-mu-ra-bi là vị vua Babylon nổi tiếng với bộ luật thành văn.'],
    ['Vì sao các nền văn minh cổ đại thường hình thành ở lưu vực sông lớn?','Vì không cần đất canh tác','Vì sông ngăn cản mọi giao lưu','Vì có nước, phù sa và điều kiện thuận lợi cho sản xuất nông nghiệp','Vì không có thiên tai',2,'Nguồn nước và phù sa hỗ trợ trồng trọt, cư trú và phát triển cộng đồng.'],
    ['Người Ai Cập cổ đại sử dụng vật liệu nào để làm giấy viết nổi tiếng?','Tre nứa','Lụa tơ tằm','Da thuộc','Cây pa-pi-rút',3,'Giấy pa-pi-rút được làm từ một loài cây mọc ven sông Nin.'],
    ['Thành tựu lịch pháp của cư dân Ai Cập cổ đại có liên quan đến nhu cầu nào?','Theo dõi thời gian và chu kì lũ sông Nin, tổ chức sản xuất','Tìm đường bay vào vũ trụ','Dự báo động đất chính xác','Đo tốc độ internet',0,'Lịch giúp xác định mùa vụ và tổ chức các hoạt động xã hội.'],
    ['Nhà nước cổ đại ở Ai Cập thường gắn với quyền lực của ai?','Hội đồng học sinh','Pha-ra-ông','Thủ lĩnh hàng hải Hy Lạp','Quan chấp chính La Mã',1,'Pha-ra-ông là người đứng đầu nhà nước Ai Cập cổ đại.'],
    ['Một bảng đất sét có dấu khắc hình nêm được tìm thấy tại vùng Lưỡng Hà. Nhận định nào phù hợp?','Đó chắc chắn là chữ tượng hình Ai Cập','Đó là chữ viết hiện đại','Có thể là tư liệu chữ viết của cư dân Lưỡng Hà, cần nghiên cứu nội dung và niên đại','Đó là bản đồ vệ tinh',2,'Chữ hình nêm là đặc trưng của nhiều tư liệu văn tự Lưỡng Hà.'],
    ['Điểm chung nổi bật về điều kiện tự nhiên của Ai Cập và Lưỡng Hà cổ đại là gì?','Đều nằm ở vùng băng giá quanh năm','Đều không có sông','Đều hình thành trên đảo núi lửa','Đều gắn với các lưu vực sông lớn',3,'Cả hai nền văn minh đều phát triển ở những vùng đồng bằng ven sông.'],
    ['Khi so sánh hai nền văn minh, cách làm nào giúp tránh nhầm lẫn thành tựu?','Gắn mỗi thành tựu với đúng khu vực, tư liệu và bối cảnh lịch sử','Cho rằng mọi thành tựu đều xuất hiện ở cùng một nơi','Chỉ dựa vào tên gọi ngày nay','Bỏ qua nguồn gốc tư liệu',0,'Đối chiếu địa điểm và bối cảnh giúp phân biệt thành tựu của từng nền văn minh.'],
    ['Một cộng đồng ven sông xây dựng kênh mương quy mô lớn. Hoạt động này gợi ra nhu cầu xã hội nào?','Chỉ phục vụ trang trí','Tổ chức lao động và quản lí nguồn nước chung','Không cần sự phối hợp','Thay thế hoàn toàn nông nghiệp',1,'Công trình thủy lợi đòi hỏi sự phối hợp và tổ chức cộng đồng.'],
    ['Vì sao chữ viết được xem là thành tựu quan trọng của các nhà nước cổ đại?','Vì chữ viết làm cho mọi người cùng nói một ngôn ngữ','Vì chữ viết thay thế hoàn toàn truyền miệng','Vì giúp ghi chép, quản lí và lưu truyền tri thức qua thời gian','Vì chữ viết chỉ dùng để trang trí',2,'Chữ viết hỗ trợ quản lí nhà nước, trao đổi và lưu giữ tri thức.']
  ]),status:'draft'},

  {lessonId:'g6-history-08',grade:6,strand:'history',title:"Ấn Độ cổ đại",questions:buildQuestions('g6-history-08',[
    ["Nền văn minh sông Ấn phát triển chủ yếu ở lưu vực con sông nào?","Sông Nin","Sông Ấn","Sông Hoàng Hà","Sông Ti-grơ",1,"Tên gọi văn minh sông Ấn gắn với lưu vực sông Ấn ở Nam Á."],
    ["Hai đô thị tiêu biểu của văn minh sông Ấn là địa điểm nào?","Ha-ráp-pa và Mô-hen-giô Đa-rô","A-ten và Xpác-ta","Ba-bi-lon và Ni-ni-ve","Mem-phít và Thebes",0,"Ha-ráp-pa và Mô-hen-giô Đa-rô là hai trung tâm đô thị nổi bật."],
    ["Đặc điểm nào thường được nhắc đến khi mô tả đô thị sông Ấn?","Nhà cửa hoàn toàn du mục","Không có đường phố","Quy hoạch đường phố và hệ thống thoát nước","Chỉ có lều tạm",2,"Nhiều di tích cho thấy đô thị được quy hoạch và có hệ thống thoát nước."],
    ["Một nguồn tư liệu quan trọng để tìm hiểu văn minh sông Ấn là gì?","Truyện khoa học viễn tưởng","Bản tin hiện đại","Dự báo thời tiết","Di tích đô thị, đồ gốm và con dấu khảo cổ",3,"Di tích và hiện vật khảo cổ là chứng cứ quan trọng về đời sống cư dân."],
    ["Khu vực hình thành nền văn minh Ấn Độ cổ đại thuộc châu lục nào?","Châu Á","Châu Âu","Châu Phi","Châu Đại Dương",0,"Ấn Độ cổ đại hình thành ở khu vực Nam Á thuộc châu Á."],
    ["Văn học Vê-đa gắn với cộng đồng cư dân nào trong lịch sử Ấn Độ cổ đại?","Người La Mã","Người Arya","Người Phoenicia","Người Maya",1,"Các bộ kinh Vê-đa gắn với người Arya và văn hóa Vê-đa."],
    ["Tôn giáo nào ra đời ở Ấn Độ cổ đại, gắn với Thích-ca Mâu-ni?","Ki-tô giáo","Hồi giáo","Phật giáo","Nho giáo",2,"Phật giáo ra đời ở Ấn Độ cổ đại, gắn với giáo pháp của Thích-ca Mâu-ni."],
    ["Ai là vị vua Maurya nổi tiếng với việc truyền bá Phật giáo?","A-lếch-xan-đơ","Ha-mu-ra-bi","Julius Caesar","A-sô-ca",3,"A-sô-ca bảo trợ Phật giáo và góp phần truyền bá tôn giáo này."],
    ["Vương triều Maurya thống nhất phần lớn tiểu lục địa Ấn Độ vào khoảng thời gian nào?","Thế kỉ III trước Công nguyên","Thế kỉ X","Thế kỉ XV","Thế kỉ XIX",0,"Đế quốc Maurya đạt đỉnh cao dưới thời A-sô-ca vào thế kỉ III TCN."],
    ["Một thành tựu toán học quan trọng của người Ấn Độ cổ đại là gì?","Phát minh máy hơi nước","Phát triển hệ chữ số thập phân và kí hiệu số 0","Chế tạo động cơ phản lực","Sáng tạo internet",1,"Toán học Ấn Độ có đóng góp lớn vào hệ thập phân và kí hiệu số 0."],
    ["Tôn giáo nào khác cũng ra đời ở Ấn Độ cổ đại, nhấn mạnh bất bạo lực và khổ hạnh?","Thần đạo","Đạo giáo","Kì-na giáo (Jain giáo)","Do Thái giáo",2,"Kì-na giáo là một tôn giáo có nguồn gốc ở Ấn Độ, đề cao bất bạo lực."],
    ["Vì sao các đô thị cổ ở lưu vực sông Ấn có điều kiện phát triển nông nghiệp?","Vì không có mùa mưa","Vì nằm hoàn toàn trên núi cao","Vì không cần nguồn nước","Vì có nguồn nước và đất đai thuận lợi ở lưu vực sông",3,"Sông cung cấp nước và góp phần tạo điều kiện cho sản xuất nông nghiệp."],
    ["Một con dấu khắc hình thú và kí hiệu được tìm thấy tại di chỉ Harappa. Cách nhận định nào thận trọng nhất?","Đó là hiện vật khảo cổ cần được phân tích để tìm hiểu trao đổi và biểu tượng","Chắc chắn là tiền giấy hiện đại","Đó là văn bản tiếng Việt","Không có giá trị nghiên cứu",0,"Con dấu là hiện vật khảo cổ; cần đặt trong bối cảnh và đối chiếu các phát hiện khác."],
    ["Khi so sánh Phật giáo và Kì-na giáo về nguồn gốc, nhận định nào phù hợp?","Cả hai đều ra đời ở La Mã","Cả hai đều có nguồn gốc ở Ấn Độ cổ đại","Cả hai chỉ xuất hiện ở châu Mỹ","Cả hai ra đời trong thế kỉ XXI",1,"Hai tôn giáo đều hình thành ở Ấn Độ cổ đại, dù giáo lí có điểm khác nhau."],
    ["Một học sinh kết luận văn minh Ấn Độ chỉ có thành tựu tôn giáo. Cách bổ sung nào đầy đủ hơn?","Chỉ kể tên các vị vua","Bỏ qua tư liệu khảo cổ","Tìm hiểu thêm đô thị, chữ viết, toán học, văn học và nghệ thuật","Cho rằng không có thành tựu khác",2,"Văn minh Ấn Độ có nhiều thành tựu về đô thị, tư tưởng, khoa học và nghệ thuật."]
  ]),status:'draft'},
  {lessonId:"g6-history-09",grade:6,strand:'history',title:"Trung Quốc từ thời cổ đại đến thế kỉ VII",questions:buildQuestions("g6-history-09",[["Hai lưu vực sông nào gắn với sự hình thành các trung tâm văn minh sớm của Trung Quốc?","Hoàng Hà và Trường Giang","Nin và Công-gô","A-ma-dôn và Pa-ra-na","Đa-nuýp và Rai-nơ",0,"Các trung tâm cư trú và văn minh sớm phát triển ở lưu vực Hoàng Hà, sau đó mở rộng đến Trường Giang."],["Phù sa của Hoàng Hà và Trường Giang tạo điều kiện thuận lợi nhất cho hoạt động nào?","Canh tác trên các đồng bằng","Khai thác băng vĩnh cửu","Chăn nuôi tuần lộc ở vùng cực","Trồng cây ôn đới trên núi băng",0,"Phù sa bồi đắp các đồng bằng rộng và tương đối màu mỡ, thuận lợi cho nông nghiệp."],["Năm 221 TCN, ai đã thống nhất Trung Quốc?","Lưu Bang","Tần Thủy Hoàng","Hán Vũ Đế","Tư Mã Thiên",1,"Tần Thủy Hoàng thống nhất các nước chư hầu vào năm 221 TCN."],["Một chính sách của nhà Tần nhằm củng cố sự thống nhất là gì?","Mỗi vùng dùng một hệ chữ viết riêng","Bỏ toàn bộ hệ thống đo lường","Thống nhất chữ viết, tiền tệ và đơn vị đo lường","Chia đất nước thành nhiều nước độc lập",2,"Chuẩn hóa chữ viết, tiền tệ, đo lường và pháp luật giúp nhà nước quản lí lãnh thổ thống nhất."],["Triều đại nào được thành lập sau cuộc thống nhất Trung Quốc năm 221 TCN?","Nhà Tần","Nhà Đường","Nhà Tống","Nhà Minh",0,"Nhà Tần được thành lập sau cuộc thống nhất năm 221 TCN."],["Ai lập ra nhà Hán sau khi nhà Tần sụp đổ?","Tào Tháo","Lưu Bang","Tùy Văn Đế","Đường Thái Tông",1,"Lưu Bang lật đổ nhà Tần và lập ra nhà Hán vào năm 206 TCN."],["Nhà Hán tồn tại trong khoảng thời gian nào theo mốc khái quát của bài học?","221–206 TCN","581–618","206 TCN–220","960–1279",2,"Nhà Hán được tính từ năm 206 TCN đến năm 220."],["Thời kì Tam quốc bắt đầu sau khi triều đại nào chấm dứt?","Nhà Tùy","Nhà Đường","Nhà Tần","Nhà Hán",3,"Nhà Hán kết thúc năm 220, sau đó Trung Quốc bước vào thời kì Tam quốc."],["Nhà Tùy thống nhất lại Trung Quốc vào năm nào?","581","221 TCN","206 TCN","907",0,"Năm 581, nhà Tùy thành lập và thống nhất lại Trung Quốc sau thời kì Nam – Bắc triều."],["Giáp cốt văn thời cổ đại Trung Quốc được khắc chủ yếu trên vật liệu nào?","Giấy dó","Mai rùa và xương thú","Lụa in màu","Đá cẩm thạch đánh bóng",1,"Giáp cốt văn là chữ được khắc trên mai rùa và xương thú, phản ánh hoạt động ghi chép thời cổ."],["Tác phẩm Sử kí nổi tiếng gắn với nhà sử học nào?","Khổng Tử","Lão Tử","Tư Mã Thiên","Ban Chiêu",2,"Tư Mã Thiên là tác giả Sử kí, một công trình sử học tiêu biểu của Trung Quốc cổ đại."],["Nếu cần sắp xếp ba mốc 221 TCN, 206 TCN và 581 theo trình tự trước đến sau, thứ tự đúng là gì?","581 → 221 TCN → 206 TCN","206 TCN → 221 TCN → 581","221 TCN → 206 TCN → 581","221 TCN → 581 → 206 TCN",2,"Trong niên đại trước Công nguyên, năm có số lớn hơn xảy ra sớm hơn; vì vậy 221 TCN trước 206 TCN, rồi đến 581."],["Một vùng đồng bằng được bồi đắp bởi phù sa của sông lớn. Hoạt động kinh tế nào có cơ sở tự nhiên thuận lợi?","Trồng trọt và định cư đông đúc hơn","Khai thác băng biển quanh năm","Chỉ phát triển săn bắt ở vùng cực","Không thể xây dựng làng mạc",0,"Đồng bằng phù sa thường thuận lợi cho trồng trọt, giao thông và hình thành khu dân cư."],["Việc nhà Tần chuẩn hóa tiền tệ và đo lường có thể giúp ích trực tiếp cho hoạt động nào?","Làm cho các vùng không thể trao đổi","Giao dịch và quản lí giữa các vùng thuận tiện hơn","Xóa bỏ mọi khác biệt địa hình","Ngăn người dân sử dụng chữ viết",1,"Đơn vị và tiền tệ thống nhất giúp trao đổi hàng hóa, thu thuế và quản lí hành chính thuận tiện hơn."],["Một bạn cho rằng mọi thành tựu kỹ thuật nổi tiếng của Trung Quốc đều được phát minh dưới thời nhà Tần. Nhận xét nào hợp lí nhất?","Đúng, vì nhà Tần kéo dài nhiều thế kỉ","Đúng, vì nhà Tần là triều đại cuối cùng","Không thể có phát minh sau nhà Tần","Không chính xác; các thành tựu xuất hiện qua nhiều thời kì khác nhau",3,"Các thành tựu văn minh Trung Quốc được hình thành qua nhiều triều đại, không chỉ trong thời nhà Tần."]]),status:'draft'},
  {lessonId:"g6-history-10",grade:6,strand:'history',title:"Hy Lạp và La Mã cổ đại",questions:buildQuestions("g6-history-10",[["Trung tâm của vùng Hy Lạp cổ đại nằm chủ yếu ở khu vực nào?","Phía nam bán đảo Ban-căng và vùng biển lân cận","Giữa sa mạc Xa-ha-ra","Lưu vực sông Nin ở Đông Phi","Đồng bằng Bắc Âu",0,"Không gian Hy Lạp cổ đại gồm phía nam bán đảo Ban-căng, các đảo và vùng ven biển quanh biển Ê-giê."],["Địa hình Hy Lạp cổ đại có đặc điểm nổi bật nào?","Đồng bằng rộng, liền mạch hoàn toàn","Nhiều núi, đồng bằng nhỏ và bờ biển chia cắt","Toàn bộ là hoang mạc cát","Bị băng tuyết phủ quanh năm",1,"Địa hình nhiều núi chia cắt đồng bằng, trong khi đường bờ biển có nhiều vịnh và đảo."],["Điều kiện tự nhiên Hy Lạp phù hợp với việc trồng một số cây lâu năm như thế nào?","Lúa mì vùng băng giá","Cây cao su nhiệt đới","Nho và ô liu","Lúa nước trên đồng bằng ngập rộng",2,"Khí hậu Địa Trung Hải và đất đai ở nhiều nơi thích hợp với nho, ô liu."],["Nhiều vũng, vịnh và hải cảng giúp cư dân Hy Lạp phát triển hoạt động nào?","Giao thương đường biển","Trồng lúa trên băng","Khai thác rừng taiga","Chăn nuôi tuần lộc",0,"Hải cảng thuận lợi cho tàu thuyền, trao đổi hàng hóa và giao lưu với vùng khác."],["Một thành bang Hy Lạp cổ đại thường gồm thành thị trung tâm và phần nào?","Một vùng băng nguyên xa xôi","Vùng đất xung quanh phục vụ sản xuất","Toàn bộ châu Âu","Chỉ có một bến cảng",1,"Thành bang là một cộng đồng chính trị có thành thị trung tâm và vùng đất phụ cận."],["A-ten là ví dụ tiêu biểu của loại hình tổ chức nào ở Hy Lạp cổ đại?","Đế quốc công nghiệp","Liên bang hiện đại","Thành bang","Thuộc địa thời cận đại",2,"A-ten là một thành bang nổi bật của Hy Lạp cổ đại."],["Trong nền dân chủ trực tiếp ở A-ten cổ đại, nhóm nào có quyền tham gia chính trị theo quy định thời đó?","Tất cả cư dân, không phân biệt","Mọi phụ nữ và trẻ em","Mọi nô lệ và người nước ngoài","Công dân nam trưởng thành",3,"Quyền chính trị ở A-ten cổ đại bị giới hạn; phụ nữ, nô lệ và người nước ngoài không có quyền như công dân nam."],["Nhà nước La Mã cổ đại hình thành đầu tiên trên khu vực nào?","Bán đảo I-ta-li-a","Bán đảo Scandinavia","Đảo Greenland","Lưu vực sông Hoàng Hà",0,"La Mã hình thành trên bán đảo I-ta-li-a ở Nam Âu."],["Biển bao quanh bán đảo I-ta-li-a tạo thuận lợi nào cho La Mã?","Cắt đứt mọi giao lưu","Kết nối hàng hải và giao thương quanh Địa Trung Hải","Chỉ phát triển nghề săn cá voi vùng cực","Không thể mở rộng lãnh thổ",1,"Vị trí ven Địa Trung Hải tạo điều kiện cho hàng hải, thương mại và liên hệ giữa các vùng."],["Trình tự các giai đoạn chính của nhà nước La Mã là gì?","Đế chế → cộng hòa → vương chính","Cộng hòa → vương chính → đế chế","Vương chính → cộng hòa → đế chế","Thành bang → phong kiến → thuộc địa",2,"Lịch sử nhà nước La Mã thường được khái quát qua thời kì vương chính, cộng hòa và đế chế."],["Đế chế Tây La Mã chấm dứt vào năm nào?","221 TCN","27 TCN","1453","476",3,"Năm 476 thường được dùng làm mốc kết thúc Đế chế Tây La Mã."],["Thế mạnh hàng hải của Hy Lạp cổ đại có thể được giải thích bằng sự kết hợp nào?","Bờ biển nhiều vịnh, đảo và nhu cầu trao đổi hàng hóa","Đồng bằng rộng và không tiếp giáp biển","Khí hậu cực lạnh và sông băng","Không có khoáng sản và sản phẩm thủ công",0,"Địa hình ven biển cùng hoạt động sản xuất, trao đổi thúc đẩy hàng hải phát triển."],["Đường sá và công trình dẫn nước của La Mã có ý nghĩa gì đối với một đế chế rộng lớn?","Làm các vùng bị cô lập","Hỗ trợ đi lại, vận chuyển và quản lí lãnh thổ","Thay thế hoàn toàn hoạt động nông nghiệp","Ngăn cản giao lưu giữa các tỉnh",1,"Hạ tầng giao thông và cấp nước góp phần kết nối đô thị, quân đội, thương mại và đời sống."],["Một công trình có hàng cột, mái tam giác và tỉ lệ cân đối thường gợi liên hệ đến thành tựu nào?","Kĩ thuật hàng không","Chữ tượng hình Ai Cập","Kiến trúc Hy Lạp cổ đại","Công nghệ vi mạch",2,"Kiến trúc đền đài với hàng cột là một dấu ấn nổi bật của Hy Lạp cổ đại."],["So sánh thành bang Hy Lạp với Đế chế La Mã, nhận định nào chính xác nhất?","Cả hai đều chỉ là một làng nông nghiệp","Thành bang Hy Lạp luôn cai trị toàn bộ Địa Trung Hải","Đế chế La Mã không có lãnh thổ ngoài thành phố Rome","Thành bang là cộng đồng chính trị quy mô nhỏ; đế chế La Mã cai quản lãnh thổ rộng lớn",3,"Thành bang Hy Lạp có quy mô chính trị riêng, còn đế chế La Mã mở rộng quyền lực trên nhiều vùng lãnh thổ."]]),status:'draft'},
  {lessonId:"g6-history-11",grade:6,strand:'history',title:"Các quốc gia sơ kì ở Đông Nam Á",questions:buildQuestions("g6-history-11",[["Một số quốc gia sơ kì ở Đông Nam Á xuất hiện trong khoảng thời gian khái quát nào?","Từ khoảng thế kỉ VII TCN đến thế kỉ VII","Chỉ từ thế kỉ XVIII đến XIX","Chỉ sau năm 1945","Từ thời kì công nghiệp hiện đại",0,"Các quốc gia sơ kì lần lượt xuất hiện trong khu vực từ khoảng thế kỉ VII TCN đến thế kỉ VII."],["Nhóm nào gồm các quốc gia sơ kì gắn với lịch sử khu vực Việt Nam?","Pa-gan, Đva-ra-va-ti, Sri Vi-giay-a","Văn Lang – Âu Lạc, Chăm-pa và Phù Nam","La Mã, A-ten và Xpác-ta","Tần, Hán và Tùy",1,"Văn Lang – Âu Lạc, Chăm-pa và Phù Nam là những quốc gia sơ kì gắn với lịch sử Việt Nam."],["Hoạt động sản xuất nào giữ vai trò quan trọng trong đời sống nhiều cộng đồng Đông Nam Á thời kì đầu?","Khai thác dầu khí ngoài khơi","Sản xuất ô tô","Trồng lúa nước","Công nghiệp điện tử",2,"Điều kiện khí hậu gió mùa, sông ngòi và đồng bằng hỗ trợ nông nghiệp lúa nước."],["Những nghề thủ công nào đã phát triển ở một số cộng đồng Đông Nam Á thời kì đầu?","Chế tạo vệ tinh và máy bay","Lắp ráp máy tính","Sản xuất nhựa tổng hợp","Đúc đồng, rèn sắt, dệt và làm gốm",3,"Nghề luyện kim, dệt và làm gốm góp phần tạo ra sản phẩm, trao đổi và tích lũy của cải."],["Điều kiện tự nhiên nào hỗ trợ nông nghiệp lúa nước ở nhiều nơi trong khu vực?","Sông ngòi, đồng bằng và khí hậu gió mùa","Băng tuyết quanh năm","Thiếu hoàn toàn nguồn nước","Hoang mạc lạnh rộng lớn",0,"Sông ngòi, lượng mưa theo mùa và đồng bằng tạo điều kiện cho trồng lúa nước."],["Các quốc gia sơ kì Đông Nam Á có quan hệ giao lưu văn hóa và kinh tế đáng kể với những khu vực nào?","Chỉ Nam Cực","Ấn Độ và Trung Quốc","Chỉ Bắc Mỹ","Chỉ vùng Bắc Cực",1,"Các tuyến giao lưu đường bộ và đường biển kết nối Đông Nam Á với Ấn Độ, Trung Quốc."],["Óc Eo là địa điểm khảo cổ nổi tiếng gắn với không gian văn hóa nào?","Bắc Âu","Địa Trung Hải","Nam Bộ","Tây Á",2,"Di chỉ Óc Eo ở Nam Bộ cung cấp nhiều bằng chứng về đời sống và giao thương cổ."],["Một cảng thị cổ thường được nhắc đến trong giao thương Đông Nam Á là địa điểm nào?","Pa-ri","Luân Đôn","Mát-xcơ-va","Ta-cô-la",3,"Ta-cô-la là một địa điểm cảng thị được nhắc đến trong các tư liệu về giao thương khu vực."],["Một đồng tiền La Mã được phát hiện tại di chỉ Óc Eo gợi ý điều gì?","Có sự giao lưu thương mại đường dài","Người La Mã đã cai trị toàn bộ Nam Bộ","Đồng tiền được đúc tại Óc Eo chắc chắn","Khu vực không có trao đổi hàng hóa",0,"Hiện vật ngoại lai là một căn cứ để nghiên cứu mạng lưới trao đổi, nhưng cần đối chiếu nhiều bằng chứng."],["Chữ Phạn và một số biểu tượng tôn giáo từ Ấn Độ xuất hiện ở Đông Nam Á cho thấy điều gì?","Văn hóa bản địa biến mất hoàn toàn","Có giao lưu và tiếp nhận, biến đổi yếu tố văn hóa","Mọi cư dân đều di cư từ Ấn Độ","Khu vực không có sáng tạo riêng",1,"Giao lưu đưa các yếu tố văn hóa đến khu vực; cư dân địa phương tiếp nhận và biến đổi theo hoàn cảnh riêng."],["Sản xuất nông nghiệp và thủ công phát triển có thể góp phần hình thành nhà nước vì sao?","Làm mọi cộng đồng ngừng trao đổi","Xóa bỏ nhu cầu tổ chức xã hội","Tạo sản phẩm dư thừa, nghề chuyên môn và nhu cầu quản lí cộng đồng","Khiến cư dân không cần hợp tác",2,"Sản phẩm dư thừa, phân công lao động và giao lưu làm xã hội phức tạp hơn, thúc đẩy nhu cầu tổ chức quyền lực."],["Một hiện vật có nguồn gốc từ vùng xa được tìm thấy ở cảng cổ. Cách giải thích thận trọng nhất là gì?","Chắc chắn có một cuộc xâm lược","Hiện vật không có giá trị nghiên cứu","Mọi cư dân đều đến từ nơi đó","Có thể đã có trao đổi, nhưng cần thêm bằng chứng để xác định cách thức",3,"Hiện vật có thể phản ánh thương mại, di cư hoặc quà tặng; cần bối cảnh khảo cổ và nguồn khác để kết luận."],["Vì sao các cửa sông và vùng ven biển có thể trở thành nơi giao thương sôi động?","Thuận tiện kết nối đường sông với tuyến hàng hải","Không có đường tiếp cận","Không thể neo đậu thuyền","Luôn cách xa khu dân cư",0,"Cửa sông và vịnh có thể kết nối vùng nội địa với tuyến vận tải biển."],["Khi so sánh hai di chỉ khảo cổ ở Đông Nam Á, học sinh nên dựa vào đâu?","Chỉ dựa vào tên gọi hiện nay","Niên đại, hiện vật, vị trí và bối cảnh khai quật","Chỉ dựa vào một lời kể chưa kiểm chứng","Số lượng khách du lịch",1,"So sánh có căn cứ cần xem xét nguồn gốc, niên đại và bối cảnh của hiện vật."],["Một bạn kết luận rằng một đồng tiền ngoại quốc chứng minh cả vùng đã bị nước ngoài cai trị. Nhận xét nào hợp lí?","Kết luận chắc chắn đúng","Chỉ cần một đồng tiền là đủ xác định biên giới","Kết luận quá vội; hiện vật có thể phản ánh trao đổi chứ không tự chứng minh quyền cai trị","Không thể nghiên cứu tiền cổ",2,"Hiện vật trao đổi không tự chứng minh sự cai trị; cần thêm tư liệu chính trị, khảo cổ và bối cảnh."]]),status:'draft'},
  {lessonId:"g6-history-12",grade:6,strand:'history',title:"Sự hình thành và bước đầu phát triển của các vương quốc phong kiến ở Đông Nam Á (từ thế kỉ VII đến thế kỉ X)",questions:buildQuestions("g6-history-12",[["Giai đoạn được bài học tập trung khi tìm hiểu các vương quốc phong kiến Đông Nam Á là thời gian nào?","Thế kỉ VII đến thế kỉ X","Thế kỉ XV đến thế kỉ XVIII","Thế kỉ XIX đến đầu thế kỉ XX","Sau năm 1945",0,"Bài học tập trung vào quá trình hình thành và phát triển ban đầu của các vương quốc phong kiến từ thế kỉ VII đến thế kỉ X."],["Pa-gan và Sri Ksetra gắn với lưu vực con sông nào?","Mê Công","I-ra-oa-đi","Hoàng Hà","Trường Giang",1,"Pa-gan và Sri Ksetra được đặt trong không gian lưu vực I-ra-oa-đi."],["Vương quốc Đva-ra-va-ti gắn với lưu vực sông nào?","Nin","A-ma-dôn","Chao Phraya","Đa-nuýp",2,"Đva-ra-va-ti phát triển trong không gian lưu vực Chao Phraya ở khu vực Thái Lan ngày nay."],["Vương quốc Chân Lạp gắn với cộng đồng cư dân nào?","Người Miến","Người Mã Lai","Người Môn","Người Khơ-me",3,"Chân Lạp gắn với người Khơ-me ở khu vực trung lưu sông Mê Công."],["Sri Vi-giay-a phát triển trên đảo nào?","Xu-ma-tra","Gia-va","Lu-dông","Ma-đa-ga-xca",0,"Sri Vi-giay-a phát triển trên đảo Xu-ma-tra, gần các tuyến hàng hải quan trọng."],["Vương quốc Ka-lin-ga gắn với đảo nào trong quần đảo In-đô-nê-xi-a?","Xu-ma-tra","Gia-va","Boóc-nê-ô","Su-la-vê-si",1,"Ka-lin-ga gắn với đảo Gia-va trong các tư liệu về các vương quốc Đông Nam Á thế kỉ VII–X."],["Đại Cồ Việt hình thành ở khu vực nào?","Bán đảo I-ta-li-a","Đảo Xu-ma-tra","Miền Bắc Việt Nam","Lưu vực sông Nin",2,"Đại Cồ Việt hình thành ở miền Bắc Việt Nam vào thế kỉ X."],["Nền tảng kinh tế quan trọng của nhiều vương quốc Đông Nam Á thời kì này là gì?","Công nghiệp cơ khí hiện đại","Khai thác than bằng máy hơi nước","Sản xuất vi mạch","Nông nghiệp, trong đó có trồng lúa nước",3,"Nông nghiệp, đặc biệt trồng lúa nước, tiếp tục là nền tảng kinh tế quan trọng."],["Vị trí gần eo biển và tuyến hàng hải đem lại lợi thế nào cho một vương quốc?","Thuận lợi kiểm soát và tham gia trao đổi hàng hóa đường biển","Không thể giao lưu với bên ngoài","Chỉ phát triển chăn nuôi vùng cực","Không cần cảng hoặc thuyền",0,"Vị trí trên tuyến hàng hải giúp vương quốc tham gia thương mại và kết nối nhiều khu vực."],["Thương mại đường biển phát triển thường thúc đẩy hoạt động nào?","Đóng cửa hoàn toàn với văn hóa khác","Trao đổi sản vật, kỹ thuật và yếu tố văn hóa","Xóa bỏ mọi đô thị cảng","Ngừng sản xuất thủ công",1,"Thương mại tạo điều kiện trao đổi hàng hóa, tri thức, tôn giáo và nghệ thuật."],["Việc một vương quốc hình thành quanh cộng đồng cư dân đông và phát triển cho thấy vai trò nào?","Không cần tổ chức quyền lực","Không có liên hệ giữa cư dân và nhà nước","Cộng đồng cư dân và tầng lớp lãnh đạo là một cơ sở tổ chức nhà nước","Mọi vương quốc đều có cùng một dân tộc",2,"Một cộng đồng cư dân có thể trở thành lực lượng nòng cốt, nhưng mỗi vương quốc có lịch sử và thành phần riêng."],["Một thương nhân đi qua vùng eo biển có nhiều cảng và trao đổi gia vị. Điều này phản ánh lợi thế nào?","Vị trí xa mọi tuyến giao thông","Chỉ có nông nghiệp tự cấp","Không có liên hệ với các vùng khác","Vị trí hàng hải thuận lợi cho thương mại khu vực",3,"Các eo biển và cảng biển có thể kết nối tuyến thương mại giữa nhiều khu vực."],["Nếu sản phẩm nông nghiệp tăng và nghề thủ công phát triển, vương quốc có thể đạt kết quả nào?","Có thêm hàng hóa để trao đổi và nguồn lực cho đô thị","Mọi hoạt động buôn bán chấm dứt","Dân cư buộc phải rời khỏi đồng bằng","Không thể phát triển tổ chức nhà nước",0,"Sản phẩm dư thừa và nghề chuyên môn tạo cơ sở cho trao đổi, thu thuế và phát triển đô thị."],["Một dấu tích kiến trúc chịu ảnh hưởng Ấn Độ nhưng có phong cách địa phương cho thấy điều gì?","Sự sao chép hoàn toàn, không có biến đổi","Sự tiếp biến văn hóa qua giao lưu","Không có liên hệ lịch sử","Chỉ có ảnh hưởng từ châu Âu",1,"Tiếp biến văn hóa là quá trình tiếp nhận và biến đổi yếu tố bên ngoài trong môi trường bản địa."],["Nhận định nào phân biệt hợp lí quốc gia sơ kì với vương quốc phong kiến hình thành về sau?","Hai khái niệm luôn chỉ cùng một giai đoạn","Các vương quốc phong kiến xuất hiện trước mọi quốc gia sơ kì","Vương quốc phong kiến thế kỉ VII–X kế thừa những cơ sở kinh tế, xã hội và chính trị đã hình thành trước đó","Quốc gia sơ kì chỉ xuất hiện sau thế kỉ XX",2,"Các vương quốc phong kiến hình thành về sau dựa trên nền tảng cư dân, sản xuất và giao lưu của những giai đoạn trước."]]),status:'draft'},
  {lessonId:"g6-history-13",grade:6,strand:'history',title:"Giao lưu văn hóa ở Đông Nam Á từ đầu Công nguyên đến thế kỉ X",questions:buildQuestions("g6-history-13",[["Trong những thế kỉ đầu Công nguyên, cư dân Đông Nam Á giao lưu văn hóa nổi bật với những khu vực nào?","Ấn Độ và Trung Quốc","Bắc Cực và Nam Cực","Chỉ Bắc Mỹ","Chỉ Tây Âu",0,"Tư liệu về Đông Nam Á cho thấy quá trình giao lưu lâu dài với Ấn Độ và Trung Quốc."],["Hai tôn giáo có ảnh hưởng quan trọng đến nhiều cộng đồng Đông Nam Á trong thời kì này là gì?","Do Thái giáo và Thần đạo","Ấn Độ giáo và Phật giáo","Tin Lành và Hồi giáo hiện đại","Chỉ các tín ngưỡng Bắc Âu",1,"Ấn Độ giáo và Phật giáo được truyền bá, tiếp nhận và biến đổi ở nhiều nơi trong khu vực."],["Những tín ngưỡng dân gian nào đã tồn tại trong cộng đồng Đông Nam Á?","Chỉ thờ các vị thần La Mã","Chỉ thờ các hoàng đế Trung Hoa","Thờ cúng tổ tiên, cầu mưa và tín ngưỡng phồn thực","Không có tín ngưỡng",2,"Các tín ngưỡng bản địa như thờ cúng tổ tiên, cầu mưa và phồn thực tiếp tục tồn tại."],["Nhiều hệ chữ viết cổ ở Đông Nam Á được xây dựng có ảnh hưởng từ hệ thống chữ nào?","Chữ hình nêm Lưỡng Hà duy nhất","Chữ La-tinh hiện đại","Chữ Cyrillic","Các hệ chữ cổ của Ấn Độ",3,"Nhiều cộng đồng trong khu vực phát triển chữ viết riêng trên cơ sở tiếp nhận hệ chữ cổ từ Ấn Độ."],["Người Việt trong thời kì này kế thừa hệ thống chữ viết nào từ Trung Quốc?","Chữ Hán","Chữ Hy Lạp","Chữ La-tinh","Chữ tượng hình Maya",0,"Người Việt tiếp nhận và sử dụng chữ Hán trong một số lĩnh vực dưới ảnh hưởng của Trung Quốc."],["Hai bộ sử thi Ấn Độ có ảnh hưởng đến văn học Đông Nam Á là gì?","I-li-át và Ô-đi-xê","Ma-ha-bha-ra-ta và Ra-ma-y-a-na","Sử kí và Hán thư","Thần khúc và Đôn Ki-hô-tê",1,"Ma-ha-bha-ra-ta và Ra-ma-y-a-na được tiếp nhận, chuyển thể thành các tác phẩm mang sắc thái địa phương."],["Khu di tích Mỹ Sơn ở Việt Nam thể hiện rõ ảnh hưởng văn hóa nào trong kiến trúc?","Kiến trúc Bắc Âu thời trung cổ","Kiến trúc La Mã hiện đại","Kiến trúc tôn giáo có ảnh hưởng Ấn Độ giáo","Kiến trúc công nghiệp thế kỉ XX",2,"Mỹ Sơn là quần thể đền tháp Chăm-pa chịu ảnh hưởng rõ nét của Ấn Độ giáo."],["Borobudur ở Indonesia là công trình kiến trúc gắn với tôn giáo nào?","Nho giáo","Do Thái giáo","Thần đạo","Phật giáo",3,"Borobudur là quần thể kiến trúc Phật giáo nổi tiếng ở Indonesia."],["Một hình thức nghệ thuật điêu khắc phổ biến ở Đông Nam Á thời kì này là gì?","Phù điêu và tượng thần, tượng Phật","Tranh sơn dầu hiện đại duy nhất","Ảnh kỹ thuật số","Tượng máy móc công nghiệp",0,"Phù điêu, tượng thần và tượng Phật là những loại hình tiêu biểu trong nghệ thuật điêu khắc."],["Sự giao lưu văn hóa không đồng nghĩa với điều gì?","Các cộng đồng học hỏi lẫn nhau","Mọi truyền thống bản địa biến mất hoàn toàn","Xuất hiện những hình thức nghệ thuật mới","Tôn giáo và chữ viết được tiếp nhận có chọn lọc",1,"Cư dân Đông Nam Á tiếp nhận nhiều yếu tố bên ngoài nhưng vẫn duy trì và phát triển truyền thống bản địa."],["Một tấm bia dùng chữ Phạn được tìm thấy ở Đông Nam Á có thể là bằng chứng cho điều gì?","Chắc chắn có một cuộc xâm lược","Không có trao đổi văn hóa","Ảnh hưởng của chữ viết và giao lưu với Ấn Độ","Mọi cư dân đều nói tiếng Phạn",2,"Bia chữ Phạn là một dấu tích của giao lưu văn hóa, không tự chứng minh mọi cư dân đều sử dụng ngôn ngữ đó."],["Một cộng đồng tiếp nhận Phật giáo nhưng vẫn duy trì lễ hội cầu mưa truyền thống. Trường hợp này thể hiện điều gì?","Từ chối mọi giao lưu","Sự biến mất hoàn toàn của tín ngưỡng cũ","Không có thay đổi văn hóa","Sự dung hợp giữa yếu tố mới và tín ngưỡng bản địa",3,"Các yếu tố văn hóa mới có thể dung hợp với tín ngưỡng địa phương thay vì thay thế hoàn toàn."],["Một sử thi Ấn Độ được kể lại bằng ngôn ngữ và nhân vật địa phương. Đây là biểu hiện nào?","Tiếp biến văn học qua giao lưu văn hóa","Sao chép nguyên vẹn không thay đổi","Không có liên hệ văn hóa","Chỉ là hoạt động buôn bán",0,"Việc chuyển thể theo ngôn ngữ và bối cảnh địa phương cho thấy quá trình tiếp nhận có sáng tạo."],["Khi nghiên cứu một công trình đền tháp cổ, học sinh nên kết hợp những nguồn nào?","Chỉ dựa vào một bức ảnh hiện nay","Kiến trúc, tượng trang trí, văn bia và bối cảnh lịch sử","Chỉ dựa vào tên gọi truyền miệng","Chỉ xem số lượng khách tham quan",1,"Đối chiếu nhiều loại tư liệu giúp nhận biết ảnh hưởng văn hóa và bối cảnh xây dựng."],["Nhận định nào giải thích đầy đủ nhất về giao lưu văn hóa Đông Nam Á từ đầu Công nguyên đến thế kỉ X?","Khu vực chỉ tiếp nhận văn hóa từ một nước","Mọi cộng đồng có văn hóa hoàn toàn giống nhau","Các yếu tố Ấn Độ và Trung Quốc được tiếp nhận, biến đổi trong nền tảng văn hóa bản địa đa dạng","Không có ảnh hưởng nào từ bên ngoài",2,"Giao lưu diễn ra nhiều chiều; cư dân địa phương chọn lọc và sáng tạo nên các hình thức văn hóa riêng."]]),status:'draft'},
  {lessonId:"g6-history-14",grade:6,strand:'history',title:"Nhà nước Văn Lang - Âu Lạc",questions:buildQuestions("g6-history-14",[["Nhà nước Văn Lang ra đời vào khoảng thời gian nào theo chương trình lớp 6?","Khoảng thế kỉ VII TCN","Thế kỉ XV","Năm 1945","Thế kỉ XXI",0,"Văn Lang được xác định hình thành vào khoảng thế kỉ VII trước Công nguyên."],["Kinh đô của nước Văn Lang gắn với địa danh nào?","Cổ Loa","Phong Châu","Hoa Lư","Thăng Long",1,"Phong Châu là trung tâm của nhà nước Văn Lang."],["Theo sơ đồ tổ chức nhà nước Văn Lang, người đứng đầu nhà nước là ai?","Lạc tướng","Bồ chính","Hùng Vương","Thái thú",2,"Hùng Vương đứng đầu nhà nước Văn Lang; dưới có các bộ và đơn vị cư trú."],["Nước Văn Lang được chia thành bao nhiêu bộ theo sơ đồ khái quát trong bài học?","5","10","12","15",3,"Theo nội dung bài học, Văn Lang chia làm 15 bộ."],["Một nhu cầu chung góp phần thúc đẩy sự ra đời của nhà nước Văn Lang là gì?","Cùng làm thủy lợi và bảo vệ cộng đồng","Xây dựng nhà máy điện","Mở đường sắt xuyên lục địa","Chinh phục không gian",0,"Nhu cầu phối hợp sản xuất, trị thủy và chống ngoại xâm góp phần thúc đẩy sự hình thành nhà nước."],["Ai lãnh đạo việc thành lập nước Âu Lạc?","Hùng Vương thứ nhất","Thục Phán, xưng An Dương Vương","Lý Bí","Ngô Quyền",1,"Thục Phán lãnh đạo người Lạc Việt và Âu Việt, sau đó xưng An Dương Vương."],["Nước Âu Lạc được thành lập vào khoảng năm nào theo bài học?","Năm 40","Năm 938","Khoảng năm 208 TCN","Năm 1010",2,"Âu Lạc được thành lập khoảng năm 208 trước Công nguyên."],["Kinh đô của nước Âu Lạc được đặt ở đâu?","Phong Châu","Mê Linh","Hoa Lư","Cổ Loa",3,"An Dương Vương chuyển trung tâm từ Phong Châu xuống Cổ Loa."],["Công trình phòng thủ nổi bật gắn với nước Âu Lạc là gì?","Thành Cổ Loa","Thành nhà Hồ","Kinh thành Huế","Hoàng thành Thăng Long",0,"Thành Cổ Loa là công trình phòng thủ lớn, có cấu trúc nhiều vòng thành."],["Những cộng đồng nào liên kết trong quá trình hình thành Âu Lạc?","Người Chăm và người Khmer","Người Lạc Việt và người Âu Việt","Người Hán và người Tần","Người La Mã và người Hy Lạp",1,"Sự liên kết giữa người Lạc Việt và Âu Việt gắn với sự ra đời của Âu Lạc."],["Một dấu tích khảo cổ tiêu biểu ở Cổ Loa là gì?","Máy hơi nước","Đồng hồ cơ khí","Lẫy nỏ và mũi tên đồng","Đường ray xe lửa",2,"Lẫy nỏ và mũi tên đồng là những hiện vật được tìm thấy ở khu vực Cổ Loa."],["Nếu so sánh hai kinh đô, nhận định nào đúng?","Cả hai đều ở vùng Nam Bộ","Cả hai đều ở miền Trung","Văn Lang ở Cổ Loa, Âu Lạc ở Phong Châu","Văn Lang gắn với Phong Châu, Âu Lạc gắn với Cổ Loa",3,"Phong Châu là trung tâm Văn Lang; Cổ Loa là kinh đô Âu Lạc."],["Một cộng đồng cần đắp đê, điều tiết nước và tổ chức sản xuất trên diện rộng. Điều này thúc đẩy nhu cầu nào?","Có tổ chức điều phối và quản lí chung","Ngừng hợp tác giữa các làng","Bỏ hoạt động nông nghiệp","Chuyển toàn bộ dân cư ra biển",0,"Thủy lợi và sản xuất chung đòi hỏi sự phối hợp, góp phần hình thành tổ chức quyền lực."],["Thành Cổ Loa có nhiều vòng thành và hệ thống phòng thủ. Điều đó phản ánh điều gì?","Chỉ phục vụ hoạt động buôn bán","Nhu cầu tổ chức phòng thủ và bảo vệ trung tâm nước Âu Lạc","Không có hoạt động xây dựng","Chỉ dùng làm nơi thờ tự",1,"Cấu trúc thành nhiều vòng cho thấy vai trò phòng thủ của Cổ Loa."],["Nhận định nào phù hợp nhất về quá trình chuyển từ Văn Lang sang Âu Lạc?","Hai nhà nước hoàn toàn không liên quan","Âu Lạc ra đời trước Văn Lang","Âu Lạc kế thừa một số cơ sở của Văn Lang và có sự liên kết Lạc Việt – Âu Việt","Văn Lang được thành lập sau thế kỉ XX",2,"Âu Lạc kế thừa một số cơ sở tổ chức của Văn Lang, đồng thời mở rộng liên kết và tăng cường phòng thủ."]]),status:'draft'},
  {lessonId:"g6-history-15",grade:6,strand:'history',title:"Chính sách cai trị của các triều đại phong kiến phương Bắc và sự chuyển biến của xã hội Âu Lạc",questions:buildQuestions("g6-history-15",[["Sau khi Âu Lạc bị thôn tính, các triều đại phương Bắc áp đặt điều gì lên cư dân địa phương?","Bộ máy cai trị và đơn vị hành chính của chính quyền đô hộ","Chế độ bầu cử phổ thông hiện đại","Một nhà nước độc lập do cư dân tự lập","Hệ thống nghị viện ngày nay",0,"Chính quyền đô hộ tổ chức bộ máy hành chính để kiểm soát lãnh thổ và cư dân."],["Một chính sách kinh tế thường được áp dụng trong thời kì Bắc thuộc là gì?","Miễn mọi nghĩa vụ cho cư dân","Thu thuế, cống nạp và chiếm đoạt nguồn lợi","Chia đều toàn bộ ruộng đất","Cấm mọi hoạt động sản xuất",1,"Thuế khóa, cống nạp và việc chiếm đoạt nguồn lợi là những hình thức bóc lột kinh tế."],["Chính quyền đô hộ thường chia địa bàn thành các đơn vị hành chính để làm gì?","Tổ chức lễ hội mùa màng","Phát triển du lịch","Tăng cường kiểm soát và quản lí cư dân","Xóa bỏ mọi hoạt động giao thông",2,"Việc chia châu, quận, huyện giúp chính quyền đô hộ kiểm soát và điều hành địa bàn."],["Việc độc quyền một số mặt hàng như sắt và muối nhằm mục đích gì?","Tạo điều kiện để cư dân tự do sản xuất mọi mặt hàng","Khuyến khích mọi làng tự trị","Xóa bỏ trao đổi hàng hóa","Kiểm soát nguồn lợi và tăng sự lệ thuộc kinh tế",3,"Độc quyền một số mặt hàng là cách kiểm soát nguồn lực và thu lợi cho chính quyền đô hộ."],["Chính sách đồng hóa văn hóa thường hướng đến điều gì?","Áp đặt phong tục, tập quán và ảnh hưởng văn hóa của chính quyền đô hộ","Khuyến khích mọi phong tục địa phương phát triển tự do","Bảo tồn toàn bộ thiết chế bản địa","Chỉ xây dựng đường giao thông",0,"Chính sách đồng hóa nhằm thay đổi một số phong tục, tập quán và đời sống văn hóa của cư dân."],["Một chuyển biến trong sản xuất của cư dân Âu Lạc thời Bắc thuộc là gì?","Mọi nghề thủ công biến mất","Nông nghiệp và một số nghề thủ công tiếp tục phát triển","Không còn trồng lúa","Chỉ còn hoạt động săn bắt",1,"Nông nghiệp, rèn sắt, đúc đồng, làm gốm và một số nghề thủ công vẫn được duy trì, phát triển."],["Tầng lớp hào trưởng bản địa hình thành và có vai trò trong xã hội. Đây là biểu hiện nào?","Không có thay đổi xã hội","Mọi cư dân có vị thế giống nhau","Cơ cấu xã hội có sự phân hóa và xuất hiện tầng lớp mới","Xã hội không còn cộng đồng làng",2,"Thời kì Bắc thuộc chứng kiến sự phân hóa xã hội và sự xuất hiện, phát triển của một số tầng lớp."],["Một trung tâm hành chính quan trọng của chính quyền đô hộ thời Hán ở nước ta là nơi nào?","Cổ Loa","Phong Châu","Hoa Lư","Luy Lâu",3,"Luy Lâu là một trị sở quan trọng của chính quyền đô hộ thời Hán."],["Những công việc nào giúp nông nghiệp phát triển trong thời kì này?","Đắp đê và làm thủy lợi","Chỉ khai thác vàng","Ngừng trồng trọt","Chỉ buôn bán đường biển",0,"Đắp đê và thủy lợi góp phần duy trì, mở rộng sản xuất nông nghiệp."],["Nhận định nào phản ánh đúng đời sống văn hóa của người Việt trong thời kì Bắc thuộc?","Mọi phong tục bản địa bị xóa bỏ ngay lập tức","Nhiều phong tục, tiếng nói và truyền thống bản địa vẫn được duy trì","Người Việt không còn cộng đồng làng","Không có hoạt động văn hóa",1,"Dù chịu sức ép đồng hóa, nhiều yếu tố văn hóa bản địa vẫn được bảo tồn và phát triển."],["Một hiện vật gốm và công cụ sắt được tìm thấy trong di chỉ thời Bắc thuộc có thể giúp nhà nghiên cứu tìm hiểu điều gì?","Chính xác mọi chính sách thuế khóa","Tất cả cư dân đều là quan lại","Hoạt động sản xuất và đời sống vật chất","Không có hoạt động thủ công",2,"Hiện vật sản xuất giúp nghiên cứu nghề thủ công, công cụ và đời sống vật chất trong bối cảnh cụ thể."],["Nếu một chính quyền áp đặt thuế nặng và bắt cống nạp sản vật, tác động trực tiếp nào có thể xảy ra?","Mọi gia đình đều giàu lên","Nhu cầu lao động biến mất","Sản xuất tự động tăng gấp đôi","Đời sống cư dân chịu thêm gánh nặng kinh tế",3,"Thuế và cống nạp làm tăng gánh nặng, ảnh hưởng đến nguồn lực của cộng đồng."],["Một cộng đồng vẫn duy trì tiếng nói và lễ tục của mình dù chịu ảnh hưởng văn hóa bên ngoài. Điều đó cho thấy gì?","Sức sống và khả năng bảo tồn văn hóa bản địa","Không có giao lưu văn hóa","Không có thay đổi xã hội","Mọi yếu tố bên ngoài đều bị từ chối",0,"Cư dân có thể tiếp nhận yếu tố mới nhưng vẫn bảo tồn các truyền thống quan trọng."],["Khi đánh giá chính sách cai trị, cách làm nào đáng tin cậy hơn?","Chỉ dựa vào một lời kể không rõ nguồn","Đối chiếu văn bản, di tích, hiện vật và bối cảnh lịch sử","Chỉ dựa vào cảm xúc hiện nay","Bỏ qua sự khác nhau giữa các thời kì",1,"Đối chiếu nhiều nguồn giúp đánh giá chính sách và mức độ tác động một cách thận trọng."],["Nhận định nào cân bằng nhất về xã hội Âu Lạc thời Bắc thuộc?","Không có thay đổi nào về kinh tế","Mọi hoạt động sản xuất đều chấm dứt","Có những chuyển biến kinh tế, xã hội nhưng bản sắc và truyền thống bản địa vẫn được duy trì","Toàn bộ xã hội chuyển thành xã hội công nghiệp",2,"Xã hội có chuyển biến dưới tác động cai trị và giao lưu, đồng thời nhiều truyền thống bản địa vẫn tiếp tục."]]),status:'draft'},
  {lessonId:"g6-history-16",grade:6,strand:'history',title:"Các cuộc khởi nghĩa tiêu biểu giành độc lập trước thế kỉ X",questions:buildQuestions("g6-history-16",[["Khởi nghĩa Hai Bà Trưng bùng nổ vào năm nào?","Năm 40","Năm 248","Năm 542","Năm 713",0,"Khởi nghĩa Hai Bà Trưng bùng nổ năm 40 và giành được quyền tự chủ trong thời gian ngắn."],["Khởi nghĩa Bà Triệu diễn ra vào năm nào?","Năm 40","Năm 248","Năm 542","Năm 938",1,"Khởi nghĩa Bà Triệu bùng nổ năm 248 ở khu vực Cửu Chân."],["Lý Bí lãnh đạo cuộc khởi nghĩa nào bùng nổ năm 542?","Khởi nghĩa Phùng Hưng","Khởi nghĩa Hai Bà Trưng","Khởi nghĩa Lý Bí","Khởi nghĩa Lam Sơn",2,"Khởi nghĩa Lý Bí bùng nổ năm 542, sau đó ông lập nước Vạn Xuân."],["Mai Thúc Loan lãnh đạo cuộc khởi nghĩa vào khoảng thời gian nào?","Năm 40–43","Năm 248","Năm 938","Năm 713–722",3,"Cuộc khởi nghĩa Mai Thúc Loan diễn ra trong giai đoạn 713–722."],["Phùng Hưng được nhân dân tôn xưng với danh hiệu nào?","Bố Cái Đại Vương","Bình Định Vương","Hưng Đạo Đại Vương","Bắc Bình Vương",0,"Phùng Hưng được nhân dân tôn xưng là Bố Cái Đại Vương."],["Một nguyên nhân quan trọng dẫn đến các cuộc khởi nghĩa thời Bắc thuộc là gì?","Mọi cư dân đều được miễn thuế","Chính sách cai trị và bóc lột nặng nề của chính quyền đô hộ","Không có cộng đồng cư dân","Sự phát triển của công nghiệp hiện đại",1,"Chính sách cai trị hà khắc, thuế khóa và cống nạp là những nguyên nhân thúc đẩy đấu tranh."],["Sau khởi nghĩa năm 40, Hai Bà Trưng đã làm gì?","Chuyển kinh đô vào Huế","Lập ra nhà Lý","Giành quyền tự chủ và xây dựng chính quyền","Thống nhất toàn bộ Đông Nam Á",2,"Sau thắng lợi ban đầu, Hai Bà Trưng lên nắm quyền và xây dựng chính quyền tự chủ."],["Khởi nghĩa Bà Triệu bắt đầu ở khu vực nào?","Luy Lâu","Cổ Loa","Phong Châu","Cửu Chân",3,"Khởi nghĩa Bà Triệu bùng nổ ở Cửu Chân rồi lan rộng ra các vùng lân cận."],["Năm 544, Lý Bí xưng đế và đặt tên nước là gì?","Vạn Xuân","Đại Cồ Việt","Đại Việt","Âu Lạc",0,"Năm 544, Lý Bí xưng Lý Nam Đế và đặt tên nước là Vạn Xuân."],["Khởi nghĩa Phùng Hưng diễn ra vào khoảng thời gian nào?","Đầu thế kỉ XV","Cuối thế kỉ VIII","Thế kỉ XX","Đầu thế kỉ XI",1,"Phùng Hưng lãnh đạo cuộc nổi dậy vào cuối thế kỉ VIII."],["Thứ tự nào sắp xếp đúng các cuộc khởi nghĩa theo thời gian?","Bà Triệu → Hai Bà Trưng → Lý Bí → Mai Thúc Loan","Lý Bí → Hai Bà Trưng → Phùng Hưng → Bà Triệu","Hai Bà Trưng → Bà Triệu → Lý Bí → Mai Thúc Loan","Mai Thúc Loan → Lý Bí → Hai Bà Trưng → Bà Triệu",2,"Các mốc lần lượt là năm 40, 248, 542, 713 và cuối thế kỉ VIII."],["Một cuộc khởi nghĩa bùng nổ năm 542 và sau đó lập nước Vạn Xuân. Đó là cuộc khởi nghĩa nào?","Bà Triệu","Phùng Hưng","Hai Bà Trưng","Lý Bí",3,"Mốc năm 542 gắn với khởi nghĩa Lý Bí; năm 544 ông lập nước Vạn Xuân."],["Vì sao các cuộc khởi nghĩa dù có kết quả khác nhau vẫn có ý nghĩa lịch sử?","Thể hiện ý chí tự chủ và duy trì truyền thống đấu tranh","Vì tất cả đều thành công lâu dài","Vì chấm dứt ngay mọi cuộc chiến tranh","Vì không liên quan đến lịch sử dân tộc",0,"Các cuộc đấu tranh thể hiện tinh thần tự chủ và góp phần nuôi dưỡng truyền thống giành độc lập."],["Khi lập trục thời gian về các cuộc khởi nghĩa, học sinh nên làm gì?","Sắp xếp theo tên gọi bất kì","Ghi mốc năm và đặt sự kiện theo trình tự trước – sau","Bỏ hết các mốc thời gian","Chỉ ghi tên nhân vật không cần sự kiện",1,"Trục thời gian cần ghi mốc năm và sắp xếp sự kiện theo thứ tự thời gian."],["Một cuộc khởi nghĩa không giữ được quyền tự chủ lâu dài. Kết luận nào hợp lí nhất?","Cuộc khởi nghĩa không có ý nghĩa gì","Không cần nghiên cứu sự kiện đó","Kết quả trước mắt có thể hạn chế nhưng ý nghĩa tinh thần và lịch sử vẫn cần được đánh giá","Mọi cuộc khởi nghĩa đều có kết quả giống nhau",2,"Cần phân biệt kết quả trước mắt với ý nghĩa lâu dài đối với tinh thần và truyền thống đấu tranh."]]),status:'draft'}
  ,{lessonId:"g6-history-17",grade:6,strand:'history',title:"Cuộc đấu tranh bảo tồn và phát triển văn hóa dân tộc của người Việt",questions:buildQuestions("g6-history-17",[["Trong thời Bắc thuộc, yếu tố nào thể hiện rõ sức sống của văn hóa người Việt?","Tiếng nói và nhiều phong tục bản địa tiếp tục được duy trì","Mọi tập quán địa phương đều biến mất","Người Việt không còn sinh hoạt cộng đồng","Tất cả cư dân chỉ sử dụng một ngôn ngữ ngoại lai",0,"Việc duy trì tiếng nói, phong tục và tín ngưỡng cho thấy văn hóa bản địa vẫn có sức sống."],["Một biểu hiện của việc giữ gìn văn hóa bản địa là gì?","Chỉ sử dụng sản phẩm nhập từ bên ngoài","Duy trì tiếng nói và một số phong tục truyền thống","Không tổ chức sinh hoạt cộng đồng","Từ bỏ mọi tín ngưỡng",1,"Tiếng nói và phong tục là những yếu tố quan trọng được cộng đồng duy trì."],["Khi nghiên cứu văn hóa người Việt thời Bắc thuộc, loại tư liệu nào có thể cung cấp thông tin?","Chỉ dự báo thời tiết hiện nay","Chỉ bản đồ giao thông hiện đại","Hiện vật, di tích, văn bản và phong tục được ghi chép","Chỉ các câu chuyện tưởng tượng",2,"Nhiều loại tư liệu khác nhau giúp tìm hiểu đời sống và văn hóa trong quá khứ."],["Tiếp thu có chọn lọc văn hóa bên ngoài được hiểu là gì?","Tiếp nhận mọi yếu tố mà không cân nhắc","Từ chối tất cả những điều mới","Sao chép nguyên vẹn mọi tập quán","Lựa chọn yếu tố phù hợp và điều chỉnh theo hoàn cảnh của mình",3,"Tiếp biến văn hóa là quá trình lựa chọn, tiếp nhận và biến đổi cho phù hợp."],["Yếu tố nào sau đây là một ví dụ về tri thức, kĩ thuật được tiếp thu trong giao lưu với Trung Hoa?","Kĩ thuật làm giấy","Động cơ phản lực","Internet","Vệ tinh viễn thông",0,"Kĩ thuật làm giấy là một trong những tri thức, kĩ thuật được tiếp nhận và phát triển trong khu vực."],["Việc duy trì tiếng Việt trong đời sống cộng đồng có ý nghĩa gì?","Làm cho mọi phong tục không thay đổi","Góp phần truyền lại tri thức, ký ức và bản sắc cộng đồng","Khiến giao lưu văn hóa chấm dứt","Thay thế mọi hình thức giao tiếp khác",1,"Ngôn ngữ giúp các thế hệ giao tiếp và truyền lại kinh nghiệm, ký ức văn hóa."],["Nhận định nào phù hợp về văn hóa người Việt trong thời Bắc thuộc?","Hoàn toàn đứng ngoài mọi giao lưu","Không có sự thay đổi nào","Vừa bảo tồn yếu tố bản địa, vừa tiếp thu có chọn lọc yếu tố bên ngoài","Chỉ tiếp nhận văn hóa mà không có sáng tạo",2,"Văn hóa vừa có tính kế thừa vừa vận động qua giao lưu và sáng tạo."],["Một tập quán được nhiều thế hệ duy trì có thể cho biết điều gì?","Mọi người ở mọi vùng đều có tập quán giống nhau","Tập quán không bao giờ thay đổi","Tập quán không liên quan đến đời sống","Cộng đồng có sự tiếp nối văn hóa qua các thế hệ",3,"Sự tiếp nối tập quán là một dấu hiệu của tính liên tục văn hóa."],["Vì sao không nên kết luận rằng người Việt chỉ tiếp nhận mà không bảo tồn văn hóa riêng?","Vì nhiều biểu hiện văn hóa bản địa vẫn được duy trì trong đời sống","Vì không có giao lưu với bên ngoài","Vì mọi tư liệu đều giống nhau","Vì lịch sử không có thay đổi",0,"Tư liệu về ngôn ngữ, phong tục và tín ngưỡng cho thấy văn hóa bản địa tiếp tục tồn tại."],["Khi tìm hiểu một phong tục hiện nay, nhà nghiên cứu cần làm gì để tránh kết luận vội vàng về nguồn gốc của nó?","Chỉ dựa vào một lời kể","Đối chiếu nhiều loại tư liệu và bối cảnh lịch sử","Cho rằng phong tục nào cũng có từ một thời điểm","Không ghi lại nguồn tư liệu",1,"Cần so sánh tư liệu và bối cảnh để đánh giá nguồn gốc, sự biến đổi của phong tục."],["Một cộng đồng tiếp nhận kĩ thuật mới nhưng vẫn duy trì tiếng nói và phong tục riêng. Điều này phản ánh điều gì?","Cộng đồng đã mất bản sắc","Không có giao lưu văn hóa","Khả năng tiếp biến và phát triển văn hóa","Mọi giá trị truyền thống đều bị thay thế",2,"Tiếp nhận điều mới không đồng nghĩa với từ bỏ toàn bộ nền tảng văn hóa riêng."],["Một nhóm học sinh lập bảng về phong tục, tiếng nói và tín ngưỡng qua các thời kì. Cách sắp xếp nào giúp so sánh tốt nhất?","Ghi các ý không cần mốc thời gian","Chỉ chọn những thông tin giống nhau","Bỏ qua nguồn tư liệu","Sắp xếp theo thời gian và ghi rõ nguồn của từng thông tin",3,"Bảng theo thời gian kèm nguồn giúp nhận ra yếu tố tiếp nối và biến đổi."],["Một gia đình kể lại câu chuyện về phong tục của địa phương và đối chiếu với hiện vật ở bảo tàng. Đây là cách làm nào?","Kết hợp tư liệu truyền miệng với tư liệu hiện vật","Chỉ dùng suy đoán cá nhân","Không cần xác định bối cảnh","Thay thế tư liệu bằng ý kiến",0,"Kết hợp nhiều loại tư liệu giúp việc tìm hiểu quá khứ có cơ sở hơn."],["Khi giao lưu với nền văn hóa khác, lựa chọn nào phù hợp với tinh thần tiếp biến văn hóa?","Bắt chước tất cả mà không suy nghĩ","Học hỏi điều tiến bộ, đồng thời gìn giữ giá trị phù hợp của cộng đồng","Từ chối mọi trao đổi","Đánh giá văn hóa khác chỉ qua một biểu hiện",1,"Giao lưu có chọn lọc vừa mở rộng hiểu biết vừa giữ được những giá trị có ý nghĩa."],["Kết luận nào khái quát tốt nhất về văn hóa người Việt trong thời Bắc thuộc?","Văn hóa bản địa biến mất hoàn toàn","Văn hóa không chịu bất cứ ảnh hưởng nào","Văn hóa được bảo tồn và phát triển qua đấu tranh, kế thừa và tiếp biến","Mọi vùng đều có cùng một cách sống",2,"Quá trình lịch sử cho thấy sự kết hợp giữa bảo tồn yếu tố bản địa và tiếp thu có chọn lọc."]]),status:'draft'},
  {lessonId:"g6-history-18",grade:6,strand:'history',title:"Bước ngoặt lịch sử đầu thế kỉ X",questions:buildQuestions("g6-history-18",[["Năm 905, nhân vật nào đứng đầu cuộc nổi dậy giành quyền tự chủ ở Tống Bình?","Khúc Thừa Dụ","Dương Đình Nghệ","Ngô Quyền","Đinh Bộ Lĩnh",0,"Năm 905, Khúc Thừa Dụ tập hợp lực lượng, giành quyền kiểm soát Tống Bình và xây dựng chính quyền tự chủ."],["Khúc Hạo nối nghiệp Khúc Thừa Dụ và tiến hành cải cách vào giai đoạn nào?","Thế kỉ XV","Đầu thế kỉ X","Thế kỉ XIII","Cuối thế kỉ XI",1,"Khúc Hạo tiếp tục củng cố chính quyền tự chủ trong những năm đầu thế kỉ X."],["Mục đích quan trọng của các cải cách dưới thời Khúc Hạo là gì?","Mở rộng lãnh thổ sang châu Âu","Chuyển kinh đô vào miền Nam","Củng cố chính quyền và giảm gánh nặng cho dân","Xây dựng một hạm đội đi vòng quanh thế giới",2,"Các cải cách về quản lí và thuế khóa góp phần củng cố nền tự chủ."],["Năm 931, ai lãnh đạo lực lượng đánh đuổi quân Nam Hán và khôi phục quyền tự chủ?","Khúc Thừa Dụ","Ngô Quyền","Lê Hoàn","Dương Đình Nghệ",3,"Dương Đình Nghệ lãnh đạo cuộc kháng chiến năm 931 và khôi phục nền tự chủ."],["Quân xâm lược bị Dương Đình Nghệ đánh đuổi năm 931 thuộc thế lực nào?","Nam Hán","Nhà Tống thời Bắc Tống","Nhà Minh","Đế quốc Mông Cổ",0,"Năm 931, lực lượng của Dương Đình Nghệ đánh bại quân Nam Hán."],["Người lãnh đạo chiến thắng Bạch Đằng năm 938 là ai?","Khúc Hạo","Ngô Quyền","Dương Đình Nghệ","Lý Bí",1,"Ngô Quyền là người chỉ huy quân dân giành chiến thắng trên sông Bạch Đằng năm 938."],["Trận quyết chiến năm 938 diễn ra ở đâu?","Sông Như Nguyệt","Sông Hồng đoạn Thăng Long","Sông Bạch Đằng","Sông Tiền",2,"Trận đánh năm 938 diễn ra trên sông Bạch Đằng."],["Yếu tố tự nhiên nào được Ngô Quyền tận dụng trong kế hoạch đánh quân Nam Hán?","Gió mùa đông bắc trên sa mạc","Tuyết rơi dày","Động đất","Thủy triều lên xuống",3,"Ngô Quyền lợi dụng quy luật thủy triều để bố trí trận địa và chọn thời điểm phản công."],["Vật cản được bố trí dưới lòng sông Bạch Đằng trong trận năm 938 là gì?","Bãi cọc","Tường thành bằng đá trên núi","Hào nước quanh kinh thành","Hệ thống đường ray",0,"Bãi cọc được bố trí ở khu vực sông để hỗ trợ đánh thuyền địch khi nước triều rút."],["Quân Nam Hán bị đánh bại trong trận Bạch Đằng năm 938 do ai chỉ huy?","Trần Hưng Đạo","Lưu Hoằng Tháo","Tôn Sĩ Nghị","Thoát Hoan",1,"Lưu Hoằng Tháo chỉ huy lực lượng thủy quân Nam Hán tiến vào Bạch Đằng và bị đánh bại."],["Sau chiến thắng Bạch Đằng, Ngô Quyền xưng vương vào năm nào?","Năm 905","Năm 931","Năm 939","Năm 1010",2,"Năm 939, Ngô Quyền xưng vương và đóng đô ở Cổ Loa."],["Thứ tự nào sắp xếp đúng các sự kiện đầu thế kỉ X?","Ngô Quyền thắng Bạch Đằng → Khúc Thừa Dụ giành quyền tự chủ → Dương Đình Nghệ đánh quân Nam Hán","Dương Đình Nghệ đánh quân Nam Hán → Ngô Quyền thắng Bạch Đằng → Khúc Hạo cải cách","Khúc Hạo cải cách → Khúc Thừa Dụ giành quyền tự chủ → Ngô Quyền thắng Bạch Đằng","Khúc Thừa Dụ giành quyền tự chủ → Khúc Hạo củng cố chính quyền → Dương Đình Nghệ đánh quân Nam Hán → Ngô Quyền thắng Bạch Đằng",3,"Trình tự khái quát là năm 905, những năm tiếp theo dưới thời Khúc Hạo, năm 931 và năm 938."],["Vì sao việc chọn thời điểm nước triều rút có ý nghĩa đối với kế hoạch của Ngô Quyền?","Làm bãi cọc lộ ra và gây khó khăn cho thuyền địch","Làm cho sông biến mất hoàn toàn","Khiến quân địch không thể nhìn thấy bờ","Làm thay đổi hướng quay của Trái Đất",0,"Khi nước rút, bãi cọc có thể gây cản trở lớn đối với thuyền địch."],["Một học sinh cho rằng chiến thắng Bạch Đằng chỉ có ý nghĩa trong một trận đánh. Nhận xét nào phù hợp hơn?","Trận đánh không liên quan đến tiến trình độc lập","Chiến thắng tạo bước ngoặt quan trọng, mở ra thời kì phát triển mới của nền tự chủ","Chiến thắng chỉ giúp mở rộng thương mại","Chiến thắng diễn ra sau năm 1945",1,"Chiến thắng năm 938 chấm dứt ý đồ xâm lược của Nam Hán và có ý nghĩa lớn đối với nền độc lập."],["Nhận định nào thể hiện đầy đủ hơn vai trò của các nhân vật đầu thế kỉ X?","Chỉ một cá nhân tạo nên mọi thay đổi","Các sự kiện không liên quan đến nhau","Nhiều lực lượng và nhân vật kế tiếp nhau xây dựng, bảo vệ và củng cố nền tự chủ","Các cải cách chỉ diễn ra sau chiến thắng Bạch Đằng",2,"Quá trình tự chủ là kết quả của nhiều bước nối tiếp nhau, từ xây dựng chính quyền đến bảo vệ đất nước."]]),status:'draft'},
  {lessonId:"g6-history-19",grade:6,strand:'history',title:"Vương quốc Chăm-pa từ thế kỉ II đến thế kỉ X",questions:buildQuestions("g6-history-19",[["Vương quốc Chăm-pa hình thành ban đầu ở khu vực nào?","Tượng Lâm thuộc quận Nhật Nam","Châu thổ sông Hồng","Lưu vực sông Mã ở miền Bắc","Vùng núi Tây Bắc",0,"Năm 192, cư dân Tượng Lâm nổi dậy và lập nước Lâm Ấp, tiền thân của Chăm-pa."],["Nhân vật gắn với cuộc nổi dậy ở Tượng Lâm năm 192 là ai?","Ngô Quyền","Khu Liên","Khúc Thừa Dụ","Lý Bí",1,"Khu Liên lãnh đạo cuộc nổi dậy ở Tượng Lâm năm 192."],["Tên gọi ban đầu của nhà nước hình thành ở Tượng Lâm là gì?","Âu Lạc","Vạn Xuân","Lâm Ấp","Phù Nam",2,"Nhà nước được lập năm 192 có tên gọi ban đầu là Lâm Ấp."],["Một hoạt động kinh tế quan trọng của cư dân Chăm-pa là gì?","Chỉ săn bắt trong rừng sâu","Chỉ khai thác băng tuyết","Chỉ chăn tuần lộc","Trồng lúa, làm thủ công và buôn bán đường biển",3,"Cư dân Chăm-pa kết hợp nông nghiệp, thủ công nghiệp, khai thác sản vật và thương mại."],["Vị trí ven biển đem lại thuận lợi nào cho Chăm-pa?","Phát triển giao thương bằng đường biển","Trồng cây ở vùng băng vĩnh cửu","Không cần trao đổi hàng hóa","Ngăn mọi liên hệ với bên ngoài",0,"Vị trí ven biển và kĩ năng đi biển hỗ trợ hoạt động trao đổi trong khu vực."],["Trung tâm Simhapura gắn với địa điểm nào ngày nay?","Phan Rang","Trà Kiệu, Quảng Nam","Cổ Loa","Óc Eo",1,"Trước thế kỉ VIII, một trung tâm quan trọng của Chăm-pa đặt ở Simhapura, khu vực Trà Kiệu ngày nay."],["Trong thế kỉ VIII, kinh đô Chăm-pa dịch chuyển về khu vực nào?","Đồng bằng sông Hồng","Thăng Long","Virapura ở khu vực Phan Rang","Cổ Loa",2,"Nguồn tư liệu SGK nêu kinh đô dịch chuyển về Virapura ở khu vực Phan Rang trong thế kỉ VIII."],["Trung tâm Indrapura trong thế kỉ IX gắn với địa điểm nào?","Huế","Đà Lạt","Hà Nội","Đồng Dương, Quảng Nam",3,"Trong thế kỉ IX, trung tâm Chăm-pa đặt tại Indrapura ở Đồng Dương."],["Chữ Chăm cổ được hình thành trên cơ sở tiếp thu hệ chữ nào?","Chữ viết có nguồn gốc từ Ấn Độ, trong đó có chữ Phạn","Chữ La-tinh hiện đại","Chữ tượng hình Ai Cập","Chữ Quốc ngữ",0,"Người Chăm tiếp thu ảnh hưởng chữ viết Ấn Độ rồi cải biến để tạo hệ chữ riêng."],["Từ khoảng thế kỉ IV, người Chăm đã làm gì đối với chữ viết?","Bỏ hoàn toàn việc ghi chép","Cải biên chữ viết chịu ảnh hưởng Ấn Độ thành chữ Chăm cổ","Chỉ sử dụng chữ La-tinh","Dùng chữ số thay cho mọi văn bản",1,"Chữ Chăm cổ là kết quả của quá trình tiếp thu và sáng tạo."],["Những tôn giáo nào có ảnh hưởng đến đời sống văn hóa Chăm-pa?","Chỉ có một tín ngưỡng duy nhất","Không có tín ngưỡng hay tôn giáo","Ấn Độ giáo và Phật giáo cùng các tín ngưỡng bản địa","Chỉ có các tôn giáo hình thành ở châu Âu",2,"Đời sống tinh thần Chăm-pa đa dạng, có tín ngưỡng bản địa và ảnh hưởng của Ấn Độ giáo, Phật giáo."],["Thánh địa Mỹ Sơn là di sản tiêu biểu gắn với nền văn hóa nào?","Văn hóa Phù Nam","Văn hóa Đông Sơn","Văn hóa Sa Huỳnh","Văn hóa Chăm-pa",3,"Mỹ Sơn là quần thể đền tháp tiêu biểu của văn hóa Chăm-pa."],["Một thương nhân Chăm-pa muốn trao đổi sản vật với thương nhân ở xa. Điều kiện nào hỗ trợ hoạt động đó?","Mạng lưới cảng biển và kĩ năng đi biển","Chỉ có đường mòn trên núi cao","Không sử dụng phương tiện vận tải","Đóng cửa mọi bến cảng",0,"Hoạt động hàng hải và các điểm giao thương giúp Chăm-pa kết nối với nhiều khu vực."],["Khi so sánh Chăm-pa với cư dân Văn Lang – Âu Lạc, điểm chung hợp lí là gì?","Cả hai đều chỉ sống bằng săn bắt","Đều có nông nghiệp và các hoạt động thủ công","Đều không có giao lưu với bên ngoài","Đều sử dụng cùng một hệ chữ viết",1,"Nông nghiệp và thủ công nghiệp là những hoạt động kinh tế quan trọng ở cả hai không gian."],["Kết luận nào khái quát đúng hơn về Chăm-pa từ thế kỉ II đến thế kỉ X?","Chỉ là một cộng đồng không có tổ chức chính trị","Không có hoạt động giao thương","Là một vương quốc có kinh tế đa dạng và văn hóa phát triển qua giao lưu","Chỉ tồn tại ở vùng núi phía Bắc",2,"Chăm-pa hình thành, phát triển với kinh tế đa dạng, mạng lưới trao đổi và thành tựu văn hóa đặc sắc."]]),status:'draft'},
  {lessonId:"g6-history-20",grade:6,strand:'history',title:"Vương quốc Phù Nam",questions:buildQuestions("g6-history-20",[["Vương quốc Phù Nam hình thành khoảng thời gian nào?","Khoảng thế kỉ I","Khoảng thế kỉ X","Khoảng thế kỉ XV","Khoảng thế kỉ XX",0,"Phù Nam hình thành khoảng thế kỉ I ở khu vực hạ lưu sông Mê Công."],["Địa bàn hình thành chủ yếu của Phù Nam gắn với khu vực nào ở Việt Nam ngày nay?","Đồng bằng sông Hồng","Nam Bộ, vùng châu thổ sông Mê Công","Tây Bắc","Bắc Trung Bộ",1,"Không gian hình thành Phù Nam gắn với khu vực Nam Bộ ngày nay."],["Văn hóa khảo cổ nào thường được liên hệ với Vương quốc Phù Nam?","Đông Sơn","Sa Huỳnh","Óc Eo","Hòa Bình",2,"Văn hóa Óc Eo là một nguồn tư liệu khảo cổ quan trọng để tìm hiểu Phù Nam."],["Một nền tảng kinh tế của cư dân Phù Nam là gì?","Chỉ săn bắt thú lớn","Chỉ khai thác khoáng sản vùng núi","Chỉ đánh cá xa bờ","Nông nghiệp, thủ công nghiệp và thương mại",3,"Kinh tế Phù Nam kết hợp sản xuất nông nghiệp, nghề thủ công và trao đổi hàng hóa."],["Điều kiện tự nhiên nào hỗ trợ giao thông và thương mại của Phù Nam?","Mạng lưới sông ngòi, kênh rạch và vị trí gần biển","Băng tuyết quanh năm","Địa hình núi cao hiểm trở khắp nơi","Không có đường thủy",0,"Mạng lưới đường thủy ở vùng hạ lưu Mê Công thuận lợi cho đi lại và trao đổi."],["Hiện vật khảo cổ ở Óc Eo có thể giúp nhà nghiên cứu tìm hiểu điều gì?","Dự báo thời tiết trong tương lai","Đời sống, nghề thủ công và quan hệ trao đổi của cư dân xưa","Mạng Internet cổ đại","Lịch thi đấu thể thao",1,"Hiện vật, đồ trang sức và dấu tích cư trú cung cấp thông tin về đời sống và giao thương."],["Phù Nam từng phát triển thành một trung tâm có quan hệ rộng trong khu vực vào khoảng giai đoạn nào?","Chỉ trong thế kỉ XX","Chỉ sau năm 1975","Khoảng các thế kỉ III đến V","Sau thế kỉ XV",2,"Các thế kỉ III–V thường được xem là giai đoạn Phù Nam phát triển mạnh."],["Một hoạt động nào góp phần kết nối Phù Nam với các khu vực khác?","Chỉ trao đổi trong một làng","Không sử dụng phương tiện vận tải","Chỉ đi bộ qua núi tuyết","Buôn bán bằng đường thủy và đường biển",3,"Đường thủy và đường biển là những tuyến giao thông quan trọng của Phù Nam."],["Vương quốc Phù Nam bắt đầu suy yếu rõ rệt từ khoảng thời gian nào?","Đầu thế kỉ VI","Đầu thế kỉ I trước Công nguyên","Cuối thế kỉ XV","Giữa thế kỉ XX",0,"Phù Nam suy yếu từ đầu thế kỉ VI và cuối cùng bị Chân Lạp thôn tính vào đầu thế kỉ VII."],["Thế lực nào thôn tính Phù Nam vào đầu thế kỉ VII theo nội dung SGK?","Nam Hán","Chân Lạp","Đại Việt thời Lý","Nhà Minh",1,"Đầu thế kỉ VII, Phù Nam bị Chân Lạp thôn tính."],["Vì sao các di tích khảo cổ Óc Eo quan trọng khi nghiên cứu Phù Nam?","Chúng chỉ phản ánh khí hậu hiện nay","Chúng không liên quan đến con người","Chúng lưu lại dấu tích về cư trú, sản xuất, thủ công và trao đổi","Chúng cho biết chính xác mọi suy nghĩ của cư dân",2,"Khảo cổ học cung cấp bằng chứng vật chất về hoạt động của con người trong quá khứ."],["Một tuyến kênh cổ nối khu cư trú với nơi trao đổi hàng hóa cho thấy điều gì?","Cư dân không biết sử dụng nước","Giao thông đường thủy không quan trọng","Mọi hoạt động đều diễn ra trên núi","Đường thủy có vai trò trong tổ chức sản xuất và giao thương",3,"Kênh rạch giúp vận chuyển người và hàng hóa, hỗ trợ hoạt động kinh tế."],["Một hiện vật trang sức tìm thấy ở di chỉ Óc Eo có thể gợi ra giả thuyết nào cần kiểm chứng?","Cư dân có nghề thủ công và có thể tham gia trao đổi hàng hóa","Tất cả cư dân đều là thương nhân","Hiện vật chắc chắn được sản xuất ở cùng một nơi","Không cần nghiên cứu thêm hiện vật",0,"Hiện vật là căn cứ để đặt giả thuyết về nghề thủ công và trao đổi, sau đó cần đối chiếu thêm."],["Điểm nào giúp phân biệt khái quát Phù Nam với Chăm-pa trong giai đoạn cổ đại?","Phù Nam nằm ở miền núi phía Bắc, Chăm-pa ở đồng bằng sông Hồng","Phù Nam gắn với Nam Bộ và văn hóa Óc Eo, Chăm-pa phát triển dọc miền Trung","Hai vương quốc có cùng một kinh đô","Cả hai đều không có hoạt động hàng hải",1,"Phù Nam gắn với vùng hạ lưu Mê Công, còn Chăm-pa phát triển dọc dải đất miền Trung."],["Kết luận nào phù hợp nhất về sự phát triển của Phù Nam?","Chỉ dựa vào một hoạt động kinh tế duy nhất","Không có liên hệ với môi trường tự nhiên","Sự kết hợp giữa nông nghiệp, thủ công, đường thủy và thương mại góp phần tạo nên sức mạnh của vương quốc","Phù Nam hình thành sau khi Chân Lạp thôn tính",2,"Điều kiện vùng châu thổ và hoạt động kinh tế đa dạng góp phần thúc đẩy Phù Nam phát triển."]]),status:'draft'},
];